struct OperatorControlRequestDraft<'a> {
    project_id: ProjectId,
    task_id: TaskId,
    operation: &'a str,
    target_ref: &'a str,
    disposition: &'a str,
    exact_action_hash: Option<String>,
    reason_or_evidence_refs: Vec<String>,
    idempotency_key: &'a str,
}

async fn persist_operator_control_request(
    state: &McpState,
    context: AuthenticatedRequestContext,
    draft: OperatorControlRequestDraft<'_>,
) -> Result<WriteReceiptRef> {
    validate_broker_text("operator control operation", draft.operation, 128)?;
    validate_broker_text("operator control target_ref", draft.target_ref, 1024)?;
    validate_broker_text("operator control disposition", draft.disposition, 128)?;
    if let Some(hash) = draft.exact_action_hash.as_deref() {
        validate_broker_text("operator exact action hash", hash, 512)?;
    }
    let expected_write_id = deterministic_canonical_write_id(
        draft.project_id,
        Some(draft.task_id),
        CanonicalReceiptKind::OperatorControlRequest,
        draft.idempotency_key,
    );
    if let Some(record) = state
        .store
        .canonical_record_by_write_id::<OperatorControlRequest>(
            draft.project_id,
            Some(draft.task_id),
            &[CanonicalReceiptKind::OperatorControlRequest.as_str()],
            expected_write_id,
        )
        .await?
    {
        let existing = &record.receipt_body;
        if existing.operation == draft.operation
            && existing.target_ref == draft.target_ref
            && existing.disposition == draft.disposition
            && existing.exact_action_hash == draft.exact_action_hash
            && existing.reason_or_evidence_refs == draft.reason_or_evidence_refs
        {
            return Ok(record.canonical_receipt);
        }
        anyhow::bail!("operator idempotency_key was already used for a different command");
    }
    let request = OperatorControlRequest {
        request_id: format!(
            "operator-control-request:{}",
            blake3::hash(draft.idempotency_key.as_bytes())
        ),
        project_id: draft.project_id,
        task_id: draft.task_id,
        operation: draft.operation.to_owned(),
        target_ref: draft.target_ref.to_owned(),
        disposition: draft.disposition.to_owned(),
        exact_action_hash: draft.exact_action_hash,
        reason_or_evidence_refs: draft.reason_or_evidence_refs,
        requested_by: format!("session:{}", context.session_id),
        created_at: time::OffsetDateTime::now_utc(),
        canonical_receipt: None,
    };
    let (receipt, _) = write_canonical_observation(
        state,
        context,
        draft.project_id,
        Some(draft.task_id),
        CanonicalReceiptKind::OperatorControlRequest,
        draft.idempotency_key,
        &request,
    )
    .await?;
    Ok(receipt)
}

struct OperatorAutonomyApprovalDecision<'a> {
    project_id: ProjectId,
    task_id: TaskId,
    approval_id: &'a str,
    exact_action_hash: &'a str,
    decision: AutonomyApprovalDecisionKind,
    reason: &'a str,
    idempotency_key: &'a str,
}

async fn execute_operator_autonomy_approval_decision(
    state: &McpState,
    context: AuthenticatedRequestContext,
    input: OperatorAutonomyApprovalDecision<'_>,
) -> Result<Value> {
    let request_write_id = approval_request_write_id(input.approval_id)?;
    let request = state
        .store
        .canonical_record_by_write_id::<AutonomyApprovalRequestRecord>(
            input.project_id,
            Some(input.task_id),
            &[CanonicalReceiptKind::AutonomyApprovalRequest.as_str()],
            request_write_id,
        )
        .await?
        .context("operator autonomy approval request does not resolve canonically")?;
    if request.receipt_body.approval_id != input.approval_id
        || request.receipt_body.project_id != input.project_id
        || request.receipt_body.task_id != input.task_id
        || request.receipt_body.request_write_id != request_write_id
        || request.canonical_receipt.write_id != request_write_id
    {
        anyhow::bail!("operator autonomy approval request scope or identity is invalid");
    }
    if request.receipt_body.exact_action_hash != input.exact_action_hash {
        anyhow::bail!("operator exact action hash differs from the canonical approval request");
    }
    dispatch_autonomy_approval_decide(
        state,
        context,
        json!({
            "project_id": input.project_id,
            "task_id": input.task_id,
            "autonomy_run_id": request.receipt_body.autonomy_run_id,
            "approval_id": input.approval_id,
            "expected_approval_revision": request.receipt_body.approval_revision,
            "decision": input.decision,
            "reason": input.reason,
            "idempotency_key": input.idempotency_key,
        }),
    )
    .await
}

fn operator_candidate_claim_id(candidate_ref: &str) -> Result<ClaimId> {
    let candidate_ref = candidate_ref.trim();
    let candidate_ref = candidate_ref
        .strip_prefix("claim:")
        .or_else(|| candidate_ref.strip_prefix("candidate:"))
        .or_else(|| candidate_ref.strip_prefix("eliot/claim/"))
        .unwrap_or(candidate_ref);
    ClaimId::from_str(candidate_ref).context("parse exact operator candidate reference")
}

async fn resolve_operator_candidate(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    candidate_ref: &str,
) -> Result<CanonicalClaimCard> {
    let claim_id = operator_candidate_claim_id(candidate_ref)?;
    let candidate = state
        .store
        .claim_card_by_id(project_id, claim_id)
        .await?
        .context("operator candidate does not resolve in the selected canonical project")?;
    if !operator_candidate_scope_matches(&candidate, project_id, task_id) {
        anyhow::bail!("operator candidate scope differs from the selected task/project");
    }
    let dispositioned = candidate
        .payload
        .get("operator_candidate_disposition")
        .is_some_and(Value::is_object);
    if candidate
        .payload
        .get("candidate_only")
        .and_then(Value::as_bool)
        != Some(true)
        && !dispositioned
    {
        anyhow::bail!("operator target is not a governed candidate-only claim");
    }
    if candidate
        .payload
        .get("provenance_refs")
        .and_then(Value::as_array)
        .is_none_or(Vec::is_empty)
    {
        anyhow::bail!("operator candidate has no canonical source provenance");
    }
    Ok(candidate)
}

fn operator_candidate_scope_matches(
    candidate: &CanonicalClaimCard,
    project_id: ProjectId,
    task_id: TaskId,
) -> bool {
    candidate.project_id == project_id && candidate.task_id == Some(task_id)
}

fn require_operator_candidate_evidence(
    candidate: &CanonicalClaimCard,
    evidence_refs: &[String],
) -> Result<Vec<String>> {
    if evidence_refs.is_empty() {
        anyhow::bail!("operator candidate disposition requires source verifier evidence");
    }
    let mut supplied = std::collections::BTreeSet::new();
    for evidence_ref in evidence_refs {
        if !supplied.insert(evidence_ref.as_str()) {
            anyhow::bail!("duplicate operator candidate evidence reference");
        }
    }
    let source_refs = candidate
        .payload
        .get("provenance_refs")
        .and_then(Value::as_array)
        .context("operator candidate has no source provenance refs")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .filter(|value| !value.trim().is_empty())
                .map(str::to_owned)
                .context("operator candidate source provenance ref is invalid")
        })
        .collect::<Result<Vec<_>>>()?;
    if source_refs.is_empty()
        || source_refs
            .iter()
            .any(|source_ref| !supplied.contains(source_ref.as_str()))
    {
        anyhow::bail!("operator evidence does not cover the candidate's exact source provenance");
    }
    Ok(source_refs)
}

fn operator_candidate_lifecycle_binding(
    candidate: &CanonicalClaimCard,
    project_id: ProjectId,
    task_id: TaskId,
    evidence_refs: &[String],
    source_provenance_refs: &[String],
    operator_session_id: SessionId,
) -> Result<OperatorLifecycleBinding> {
    Ok(OperatorLifecycleBinding {
        evidence_refs: evidence_refs.to_vec(),
        precondition_refs: vec![
            format!("candidate-claim:{}", candidate.claim_id),
            format!("candidate-write:{}", candidate.write_id),
            format!("candidate-revision:{}", candidate.memory_revision.value()),
            format!("candidate-project:{project_id}"),
            format!("candidate-task:{task_id}"),
            format!(
                "candidate-provenance-blake3:{}",
                canonical_struct_hash(&source_provenance_refs.to_vec())?
            ),
        ],
        approval_ref: Some(format!("operator-session:{operator_session_id}")),
    })
}

fn deterministic_operator_candidate_write_id(
    project_id: ProjectId,
    task_id: TaskId,
    idempotency_key: &str,
) -> WriteId {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"eliot-operator-candidate-disposition-v1");
    hasher.update(project_id.to_string().as_bytes());
    hasher.update(task_id.to_string().as_bytes());
    hasher.update(idempotency_key.as_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 16];
    bytes.copy_from_slice(&digest.as_bytes()[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x50;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    WriteId::from_uuid(uuid::Uuid::from_bytes(bytes))
}

fn candidate_promotion_replay_matches(
    candidate: &CanonicalClaimCard,
    task_id: TaskId,
    idempotency_key: &str,
    evidence_refs: &[String],
) -> bool {
    let disposition = candidate.payload.get("operator_candidate_disposition");
    candidate.status == EpistemicStatus::Verified
        && candidate.task_id == Some(task_id)
        && disposition
            .and_then(|value| value.get("disposition"))
            .and_then(Value::as_str)
            == Some("promote")
        && disposition.and_then(|value| value.get("task_id")) == Some(&json!(task_id))
        && disposition
            .and_then(|value| value.get("idempotency_key"))
            .and_then(Value::as_str)
            == Some(idempotency_key)
        && disposition.and_then(|value| value.get("evidence_refs")) == Some(&json!(evidence_refs))
}

async fn ensure_operator_candidate_is_active(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    claim_id: ClaimId,
) -> Result<()> {
    let subject_ref = format!("claim:{claim_id}");
    let lifecycle_state = state
        .store
        .canonical_records_by_subject_ref::<eliot_types::MemoryStateTransition>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::StateTransition.as_str()],
            &subject_ref,
            1,
        )
        .await?
        .into_iter()
        .next()
        .map_or(MemoryLifecycleState::Active, |record| {
            record.receipt_body.to_state
        });
    if !matches!(
        lifecycle_state,
        MemoryLifecycleState::Active | MemoryLifecycleState::Restored
    ) {
        anyhow::bail!("operator candidate already has a non-active lifecycle disposition");
    }
    Ok(())
}

struct CandidateDispositionActor {
    role_lease_id: String,
    controller_lease_id: Option<String>,
}

async fn require_candidate_disposition_actor(
    state: &McpState,
    context: AuthenticatedRequestContext,
    task: &TaskContract,
) -> Result<CandidateDispositionActor> {
    let actor = AgentSessionId::from_uuid(context.session_id.as_uuid());
    let broker = delegation_runtime::load_state(&state.root)?;
    let now = time::OffsetDateTime::now_utc();
    let eligible_roles = broker
        .task_role_leases
        .iter()
        .filter(|role| {
            role.task_id == task.task_id
                && role.agent_session_id == actor
                && role.expires_at > now
                && role
                    .capability_scope
                    .iter()
                    .any(|capability| matches!(capability.as_str(), "review" | "review_candidate"))
                && match state.profile {
                    McpAccessProfile::HumanOperator => role.role == AgentRole::Reviewer,
                    McpAccessProfile::CodexController => role.role == AgentRole::Controller,
                    _ => false,
                }
        })
        .collect::<Vec<_>>();
    let [role] = eligible_roles.as_slice() else {
        anyhow::bail!(
            "candidate disposition requires one active canonical reviewer/controller role lease"
        );
    };
    require_exact_current_projection(
        state,
        task.project_id,
        Some(task.task_id),
        "task_role_lease",
        &role.role_lease_id,
        "receipt_body",
        Some("host_role_lease_authority"),
        *role,
    )
    .await?;
    let controller_lease_id = if role.role == AgentRole::Controller {
        let controllers = broker
            .controller_leases
            .iter()
            .filter(|lease| {
                lease.task_id == task.task_id
                    && lease.agent_session_id == actor
                    && lease.expires_at > now
            })
            .collect::<Vec<_>>();
        let [controller] = controllers.as_slice() else {
            anyhow::bail!(
                "controller candidate disposition requires one active canonical ControllerLease"
            );
        };
        require_exact_current_projection(
            state,
            task.project_id,
            Some(task.task_id),
            "controller_lease",
            &controller.controller_lease_id,
            "receipt_body",
            Some("controller_lease"),
            *controller,
        )
        .await?;
        Some(controller.controller_lease_id.clone())
    } else {
        None
    };
    Ok(CandidateDispositionActor {
        role_lease_id: role.role_lease_id.clone(),
        controller_lease_id,
    })
}

struct CandidatePromotion<'a> {
    task: &'a TaskContract,
    candidate: &'a CanonicalClaimCard,
    evidence_refs: &'a [String],
    source_provenance_refs: Vec<String>,
    idempotency_key: &'a str,
    actor: &'a CandidateDispositionActor,
}

async fn existing_candidate_promotion(
    state: &McpState,
    promotion: &CandidatePromotion<'_>,
    write_id: WriteId,
) -> Result<Option<WriteReceiptRef>> {
    if let Some(receipt) = state.store.write_receipt_by_id(&write_id).await? {
        if receipt.project_id == promotion.task.project_id
            && receipt.task_id == Some(promotion.task.task_id)
            && receipt.command_kind == SemanticCommandKind::ClaimVerify
            && candidate_promotion_replay_matches(
                promotion.candidate,
                promotion.task.task_id,
                promotion.idempotency_key,
                promotion.evidence_refs,
            )
        {
            return Ok(Some(WriteReceiptRef {
                receipt_id: receipt.receipt_id,
                write_id: receipt.write_id,
            }));
        }
        anyhow::bail!("operator idempotency_key was already used for a different candidate review");
    }
    Ok(None)
}

async fn promote_operator_candidate(
    state: &McpState,
    context: AuthenticatedRequestContext,
    promotion: CandidatePromotion<'_>,
) -> Result<WriteReceiptRef> {
    let project_id = promotion.task.project_id;
    let write_id = deterministic_operator_candidate_write_id(
        project_id,
        promotion.task.task_id,
        promotion.idempotency_key,
    );
    if let Some(receipt) = existing_candidate_promotion(state, &promotion, write_id).await? {
        return Ok(receipt);
    }
    let CandidatePromotion {
        task,
        candidate,
        evidence_refs,
        source_provenance_refs,
        idempotency_key,
        actor,
    } = promotion;
    if candidate.status != EpistemicStatus::Candidate {
        anyhow::bail!("only an undispositioned candidate claim can be promoted");
    }
    ensure_operator_candidate_is_active(state, project_id, task.task_id, candidate.claim_id)
        .await?;
    let mut payload = candidate
        .payload
        .as_object()
        .cloned()
        .context("operator candidate payload must be an object")?;
    payload.insert("candidate_only".to_owned(), Value::Bool(false));
    payload.insert(
        "controller_reconciliation_required".to_owned(),
        Value::Bool(false),
    );
    payload.insert("admitted_by_operator".to_owned(), Value::Bool(true));
    payload.insert(
        "operator_candidate_disposition".to_owned(),
        json!({
            "disposition": "promote",
            "task_id": task.task_id,
            "candidate_ref": format!("claim:{}", candidate.claim_id),
            "source_write_id": candidate.write_id,
            "source_memory_revision": candidate.memory_revision,
            "idempotency_key": idempotency_key,
            "evidence_refs": evidence_refs,
            "source_provenance_refs": source_provenance_refs,
            "operator_session_id": context.session_id,
            "actor_role_lease_id": actor.role_lease_id,
            "actor_controller_lease_id": actor.controller_lease_id,
        }),
    );
    let command = SemanticCommand::ClaimVerify(eliot_types::ClaimVerifyCommand {
        context: CommandContext {
            write_id,
            agent_id: AgentId::from_uuid(context.session_id.as_uuid()),
            session_id: Some(context.session_id),
            project_id,
            task_id: Some(task.task_id),
            scope: format!("task:{}:candidate-disposition", task.task_id),
            authority: "human-operator-governed-candidate-review".to_owned(),
            visibility: Visibility::Project,
            taint: TaintClass::LocalVerified,
            lifecycle_status: LifecycleStatus::Active,
        },
        claim_id: candidate.claim_id,
        verification: VerificationRunInput {
            verification_id: VerificationId::from_uuid(write_id.as_uuid()),
            claim_id: Some(candidate.claim_id),
            verifier: format!("human-operator-session:{}", context.session_id),
            result: VerificationResult::Passed,
            summary:
                "HumanOperator admitted the candidate after reviewing its exact source evidence"
                    .to_owned(),
            payload: json!({
                "authority": "human_operator",
                "operator_session_id": context.session_id,
                "actor_role_lease_id": actor.role_lease_id,
                "actor_controller_lease_id": actor.controller_lease_id,
                "project_id": project_id,
                "task_id": task.task_id,
                "candidate_ref": format!("claim:{}", candidate.claim_id),
                "candidate_original_write_id": candidate.write_id,
                "candidate_original_revision": candidate.memory_revision,
                "idempotency_key": idempotency_key,
                "evidence_refs": evidence_refs,
                "source_provenance_refs": source_provenance_refs,
                "disposition": "promote",
            }),
        },
        statement: Some(candidate.statement.clone()),
        payload: Value::Object(payload),
    });
    let receipt = state
        .writer
        .submit(WriteAdmissionService.admit(&command)?)
        .await?;
    Ok(WriteReceiptRef {
        receipt_id: receipt.receipt_id,
        write_id: receipt.write_id,
    })
}

async fn execute_operator_candidate_review(
    state: &McpState,
    context: AuthenticatedRequestContext,
    task: &TaskContract,
    candidate_ref: &str,
    disposition: &str,
    evidence_refs: &[String],
    idempotency_key: &str,
) -> Result<(WriteReceiptRef, &'static str)> {
    let actor = require_candidate_disposition_actor(state, context, task).await?;
    let project_id = task.project_id;
    let candidate =
        resolve_operator_candidate(state, project_id, task.task_id, candidate_ref).await?;
    let source_provenance_refs = require_operator_candidate_evidence(&candidate, evidence_refs)?;
    if disposition == "promote" {
        let receipt = promote_operator_candidate(
            state,
            context,
            CandidatePromotion {
                task,
                candidate: &candidate,
                evidence_refs,
                source_provenance_refs,
                idempotency_key,
                actor: &actor,
            },
        )
        .await?;
        return Ok((receipt, "candidate_promoted_verified"));
    }
    if candidate.status != EpistemicStatus::Candidate {
        anyhow::bail!("only an undispositioned candidate claim can receive lifecycle disposition");
    }
    let subject_ref = format!("claim:{}", candidate.claim_id);
    let primary_key = format!("{idempotency_key}:primary");
    let expected_write_id = deterministic_canonical_write_id(
        project_id,
        Some(task.task_id),
        CanonicalReceiptKind::StateTransition,
        &primary_key,
    );
    let existing_transition = state
        .store
        .canonical_record_by_write_id::<eliot_types::MemoryStateTransition>(
            project_id,
            Some(task.task_id),
            &[CanonicalReceiptKind::StateTransition.as_str()],
            expected_write_id,
        )
        .await?;
    if existing_transition.is_none() {
        ensure_operator_candidate_is_active(state, project_id, task.task_id, candidate.claim_id)
            .await?;
    }
    let (operator, reason, outcome) = match disposition {
        "reject" => (
            ForgettingOperator::Suppress,
            ForgettingReason::VerifierContradicted,
            "candidate_rejected",
        ),
        "demote" => (
            ForgettingOperator::Demote,
            ForgettingReason::LowUtility,
            "candidate_demoted",
        ),
        "archive" => (
            ForgettingOperator::Archive,
            ForgettingReason::LowUtility,
            "candidate_archived",
        ),
        _ => anyhow::bail!("unsupported operator candidate disposition"),
    };
    let receipt = persist_operator_lifecycle_transition(
        state,
        context,
        project_id,
        task.task_id,
        &subject_ref,
        operator,
        reason,
        operator_candidate_lifecycle_binding(
            &candidate,
            project_id,
            task.task_id,
            evidence_refs,
            &source_provenance_refs,
            context.session_id,
        )?,
        idempotency_key,
    )
    .await?;
    Ok((receipt, outcome))
}

async fn resolve_exact_procedure_pattern(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    pattern_ref: &str,
) -> Result<(ExperiencePattern, String, String, WriteReceiptRef)> {
    let pattern_id = pattern_ref
        .strip_prefix("experience-pattern:")
        .filter(|value| !value.trim().is_empty())
        .context("pattern_ref must be experience-pattern:<exact-pattern-id>")?;
    let observations = state
        .store
        .experience_pattern_revisions_by_id(project_id, task_id, pattern_id)
        .await?;
    // ExperiencePattern history is immutable: maturity transitions append a
    // new physical observation for the same logical pattern. This exact,
    // bounded store query orders matching revisions newest-first.
    let observation = observations
        .into_iter()
        .max_by_key(|observation| (observation.memory_revision, observation.project_sequence))
        .context("pattern_ref does not resolve to a canonical ExperiencePattern")?;
    let pattern = serde_json::from_value::<ExperiencePattern>(
        observation
            .payload
            .get("receipt_body")
            .cloned()
            .context("canonical ExperiencePattern observation has no receipt_body")?,
    )
    .context("parse canonical ExperiencePattern observation")?;
    if pattern.pattern_id != pattern_id {
        anyhow::bail!("canonical ExperiencePattern id differs from pattern_ref");
    }
    if pattern.project_id != project_id
        || observation.project_id != project_id
        || observation.task_id != Some(task_id)
    {
        anyhow::bail!("ExperiencePattern project differs from requested project");
    }
    let write_id = observation.write_id;
    let receipt = state
        .store
        .write_receipt_by_id(&write_id)
        .await?
        .context("canonical ExperiencePattern observation has no WriterActor receipt")?;
    if receipt.project_id != project_id
        || receipt.task_id != Some(task_id)
        || receipt.command_kind != eliot_types::SemanticCommandKind::ToolObservationRecord
        || receipt.memory_revision != Some(observation.memory_revision)
        || receipt.project_sequence != Some(observation.project_sequence)
        || !receipt
            .created_records
            .contains(&observation.observation_id)
        || !matches!(
            receipt.status,
            WriteStatus::Committed | WriteStatus::IdempotentReplay
        )
    {
        anyhow::bail!("canonical ExperiencePattern receipt scope or status differs");
    }
    Ok((
        pattern.clone(),
        sha256_json(&pattern)?,
        observation.observation_id,
        WriteReceiptRef {
            receipt_id: receipt.receipt_id,
            write_id: receipt.write_id,
        },
    ))
}

fn task_evidence_refs(task: &TaskContract) -> BTreeSet<String> {
    let mut refs = BTreeSet::new();
    for observation_id in &task.observation_ids {
        refs.insert(observation_id.clone());
        refs.insert(format!("observation:{observation_id}"));
    }
    for verification_id in &task.verification_ids {
        refs.insert(verification_id.to_string());
        refs.insert(format!("verification:{verification_id}"));
    }
    for scope in &task.verification_scopes {
        refs.insert(scope.verification_id.to_string());
        refs.insert(format!("verification:{}", scope.verification_id));
        refs.insert(scope.verifier_id.clone());
        refs.insert(format!("verifier:{}", scope.verifier_id));
        refs.insert(scope.worktree_ref.clone());
        refs.insert(scope.path_or_resource_scope.clone());
        for artifact in &scope.artifact_refs {
            refs.insert(artifact.resource_ref.clone());
        }
    }
    refs.retain(|value| !value.trim().is_empty());
    refs
}

fn task_verifier_artifacts(task: &TaskContract) -> Vec<VerifierArtifactRef> {
    task.verification_scopes
        .iter()
        .flat_map(|scope| &scope.artifact_refs)
        .filter(|artifact| is_canonical_hash(&artifact.content_hash))
        .filter(|artifact| !artifact.resource_ref.trim().is_empty())
        .cloned()
        .collect()
}

fn validate_procedure_candidate_source_refs(
    task: &TaskContract,
    pattern: &ExperiencePattern,
    candidate: &SkillCardV2,
) -> Result<()> {
    let mut allowed = task_evidence_refs(task);
    allowed.extend(pattern.member_case_refs.iter().cloned());
    allowed.extend(pattern.authority.exact_source_refs.iter().cloned());
    allowed.extend(pattern.transfer_evidence.iter().cloned());
    if candidate
        .source_trace_refs
        .iter()
        .any(|source_ref| !allowed.contains(source_ref))
    {
        anyhow::bail!(
            "procedure candidate source_trace_refs must resolve through the exact pattern or current task evidence"
        );
    }
    Ok(())
}

fn procedure_candidate_identity(
    task: &TaskContract,
    pattern: &ExperiencePattern,
    input: &ProcedureCandidateCreateToolInput,
    pattern_sha256: &str,
    pattern_observation_ref: &str,
    pattern_receipt: &WriteReceiptRef,
) -> Result<(String, String, String)> {
    if input.candidate_skill.lifecycle_state != SkillLifecycleState::Candidate
        || input.candidate_skill.level != eliot_types::SkillLevel::Procedure
    {
        anyhow::bail!("procedure SkillCard must remain candidate-only at Procedure level");
    }
    validate_broker_text("candidate name", &input.candidate_skill.name, 256)?;
    validate_procedure_candidate_source_refs(task, pattern, &input.candidate_skill)?;
    let candidate_ref = format!("skill:{}", input.candidate_skill.skill_id);
    let candidate_sha256 = sha256_json(&input.candidate_skill)?;
    let input_fingerprint = sha256_json(&json!({
        "project_id": task.project_id,
        "task_id": task.task_id,
        "task_revision": input.expected_revision,
        "pattern_ref": input.pattern_ref,
        "pattern_observation_ref": pattern_observation_ref,
        "pattern_receipt": pattern_receipt,
        "pattern_sha256": pattern_sha256,
        "candidate_ref": candidate_ref,
        "candidate_sha256": candidate_sha256,
    }))?;
    Ok((candidate_ref, candidate_sha256, input_fingerprint))
}

fn procedure_candidate_response(
    record: &CanonicalProcedureSkillCandidate,
    canonical_receipt: &WriteReceiptRef,
    write_status: Option<WriteStatus>,
    idempotent_replay: bool,
) -> Value {
    json!({
        "component": "procedure_skill_candidate",
        "candidate": record,
        "canonical_receipt": canonical_receipt,
        "write_status": write_status,
        "idempotent_replay": idempotent_replay,
    })
}

async fn persist_procedure_candidate(
    state: &McpState,
    context: AuthenticatedRequestContext,
    idempotency_key: &str,
    record: CanonicalProcedureSkillCandidate,
) -> Result<Value> {
    let (receipt, status) = write_canonical_observation(
        state,
        context,
        record.project_id,
        Some(record.task_id),
        CanonicalReceiptKind::ProcedureSkillCandidate,
        idempotency_key,
        &record,
    )
    .await?;
    Ok(procedure_candidate_response(
        &record,
        &receipt,
        Some(status),
        matches!(status, WriteStatus::IdempotentReplay),
    ))
}

async fn dispatch_procedure_candidate_create(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    state.ensure_schema().await?;
    let input: ProcedureCandidateCreateToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse procedure task_id")?;
    validate_broker_text("idempotency_key", &input.idempotency_key, 256)?;
    let task = require_l11_task(state, project_id, task_id, input.expected_revision).await?;
    let (pattern, pattern_sha256, pattern_observation_ref, pattern_receipt) =
        resolve_exact_procedure_pattern(state, project_id, task_id, &input.pattern_ref).await?;
    let (candidate_ref, candidate_sha256, input_fingerprint) = procedure_candidate_identity(
        &task,
        &pattern,
        &input,
        &pattern_sha256,
        &pattern_observation_ref,
        &pattern_receipt,
    )?;
    let existing_candidates = state
        .store
        .canonical_records_by_subject_ref::<CanonicalProcedureSkillCandidate>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ProcedureSkillCandidate.as_str()],
            &candidate_ref,
            2,
        )
        .await?;
    if existing_candidates.len() > 1 {
        anyhow::bail!("candidate_ref resolves to ambiguous canonical SkillCard records");
    }
    if let Some(existing) = existing_candidates.into_iter().next() {
        if existing.receipt_body.input_fingerprint != input_fingerprint {
            anyhow::bail!("candidate_ref is already occupied by a different canonical SkillCard");
        }
        return Ok(procedure_candidate_response(
            &existing.receipt_body,
            &existing.canonical_receipt,
            None,
            true,
        ));
    }
    let write_id = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::ProcedureSkillCandidate,
        &input.idempotency_key,
    );
    if let Some(existing) = state
        .store
        .canonical_record_by_write_id::<CanonicalProcedureSkillCandidate>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ProcedureSkillCandidate.as_str()],
            write_id,
        )
        .await?
    {
        if existing.receipt_body.input_fingerprint != input_fingerprint {
            anyhow::bail!("procedure candidate idempotency key conflicts with another candidate");
        }
        return Ok(procedure_candidate_response(
            &existing.receipt_body,
            &existing.canonical_receipt,
            None,
            true,
        ));
    }
    let record = CanonicalProcedureSkillCandidate {
        schema_version: "eliot-procedure-skill-candidate-v1".to_owned(),
        project_id,
        task_id,
        task_revision: input.expected_revision,
        pattern_ref: input.pattern_ref,
        pattern_observation_ref,
        pattern_receipt,
        pattern_sha256,
        candidate_ref,
        candidate_sha256,
        candidate_skill: input.candidate_skill,
        input_fingerprint,
        candidate_only: true,
        activation_applied: false,
        created_at: time::OffsetDateTime::now_utc(),
    };
    persist_procedure_candidate(state, context, &input.idempotency_key, record).await
}

async fn resolve_procedure_candidate(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    candidate_ref: &str,
) -> Result<CanonicalRecord<CanonicalProcedureSkillCandidate>> {
    if candidate_ref
        .strip_prefix("skill:")
        .is_none_or(|value| value.trim().is_empty())
    {
        anyhow::bail!("candidate_ref must be skill:<exact-skill-id>");
    }
    let mut records = state
        .store
        .canonical_records_by_subject_ref::<CanonicalProcedureSkillCandidate>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ProcedureSkillCandidate.as_str()],
            candidate_ref,
            2,
        )
        .await?;
    if records.len() != 1 {
        anyhow::bail!("candidate_ref must resolve to exactly one canonical task-scoped SkillCard");
    }
    let record = records
        .pop()
        .context("canonical procedure SkillCard disappeared")?;
    if record.receipt_body.candidate_ref != candidate_ref
        || record.receipt_body.project_id != project_id
        || record.receipt_body.task_id != task_id
        || !record.receipt_body.candidate_only
        || record.receipt_body.activation_applied
        || record.receipt_body.candidate_skill.lifecycle_state != SkillLifecycleState::Candidate
    {
        anyhow::bail!("canonical procedure SkillCard violates candidate-only scope");
    }
    if sha256_json(&record.receipt_body.candidate_skill)? != record.receipt_body.candidate_sha256 {
        anyhow::bail!("canonical procedure SkillCard body hash differs");
    }
    Ok(record)
}

async fn validated_negative_transfer_refs(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    requested: &[String],
) -> Result<(Vec<String>, Vec<String>)> {
    let records = semantic_records::<eliot_types::NegativeTransferRecord>(
        state,
        project_id,
        "negative_transfer_record",
    )
    .await?;
    let task_refs = [task_id.to_string(), format!("task:{task_id}")];
    let mut validated = Vec::new();
    let mut unresolved = Vec::new();
    for reference in requested {
        let record_id = reference
            .strip_prefix("negative-transfer:")
            .unwrap_or(reference);
        if records
            .iter()
            .any(|record| record.record_id == record_id && task_refs.contains(&record.task_ref))
        {
            validated.push(reference.clone());
        } else {
            unresolved.push(reference.clone());
        }
    }
    Ok((validated, unresolved))
}

async fn validate_procedure_disposition_evidence(
    state: &McpState,
    task: &TaskContract,
    input: &ProcedureCandidateDispositionToolInput,
) -> Result<(Vec<String>, Vec<String>)> {
    let task_artifacts = task_verifier_artifacts(task);
    if input
        .holdout_evidence
        .iter()
        .any(|requested| !task_artifacts.iter().any(|artifact| artifact == requested))
    {
        anyhow::bail!(
            "every holdout_evidence item must resolve to an exact canonical current-task verifier artifact"
        );
    }
    let holdout_refs = input
        .holdout_evidence
        .iter()
        .map(|artifact| artifact.resource_ref.clone())
        .collect::<Vec<_>>();
    let (negative_refs, unresolved) = validated_negative_transfer_refs(
        state,
        task.project_id,
        task.task_id,
        &input.negative_transfer_refs,
    )
    .await?;
    if !unresolved.is_empty() {
        anyhow::bail!(
            "every negative_transfer_ref must resolve to an exact canonical current-task negative-transfer record"
        );
    }
    Ok((holdout_refs, negative_refs))
}

fn procedure_disposition_fingerprint(
    input: &ProcedureCandidateDispositionToolInput,
    task: &TaskContract,
    pattern_sha256: &str,
    pattern_observation_ref: &str,
    pattern_receipt: &WriteReceiptRef,
    candidate: &CanonicalRecord<CanonicalProcedureSkillCandidate>,
) -> Result<String> {
    sha256_json(&json!({
        "project_id": task.project_id,
        "task_id": task.task_id,
        "task_revision": input.expected_revision,
        "pattern_ref": input.pattern_ref,
        "pattern_observation_ref": pattern_observation_ref,
        "pattern_receipt": pattern_receipt,
        "pattern_sha256": pattern_sha256,
        "candidate_ref": input.candidate_ref,
        "candidate_receipt": candidate.canonical_receipt,
        "candidate_sha256": candidate.receipt_body.candidate_sha256,
        "holdout_evidence": input.holdout_evidence,
        "negative_transfer_refs": input.negative_transfer_refs,
    }))
}

fn evaluate_procedure_disposition(
    pattern: &ExperiencePattern,
    candidate: &SkillCardV2,
    holdout_refs: &[String],
    negative_refs: &[String],
    has_generic_holdout: bool,
) -> Result<(
    SkillLifecycleRecord,
    ProcedurePromotionOutcome,
    String,
    Vec<String>,
)> {
    let mut lifecycle = SkillLifecycleService::procedure_promotion_disposition(
        pattern,
        candidate,
        holdout_refs,
        negative_refs,
    );
    lifecycle.write_receipt = None;
    let engine_outcome = lifecycle
        .promotion_outcome
        .context("procedure promotion engine returned no disposition")?;
    let mut reasons = vec![if has_generic_holdout {
        "generic_task_verifier_artifact_is_not_procedure_holdout_authority".to_owned()
    } else {
        "missing_independent_procedure_holdout".to_owned()
    }];
    let outcome = if engine_outcome == ProcedurePromotionOutcome::Promoted {
        lifecycle.state = SkillLifecycleState::Candidate;
        lifecycle.promotion_outcome = Some(ProcedurePromotionOutcome::NotReadyForProcedure);
        reasons.push("procedure_holdout_semantic_kind_is_unavailable_in_v1".to_owned());
        ProcedurePromotionOutcome::NotReadyForProcedure
    } else {
        engine_outcome
    };
    let pattern_disposition = if outcome == ProcedurePromotionOutcome::Demoted {
        "candidate_quarantined_pattern_retained"
    } else {
        "kept_transfer_validated"
    };
    Ok((lifecycle, outcome, pattern_disposition.to_owned(), reasons))
}

fn procedure_disposition_response(
    record: &CanonicalProcedurePromotionDisposition,
    canonical_receipt: &WriteReceiptRef,
    write_status: Option<WriteStatus>,
    idempotent_replay: bool,
) -> Value {
    json!({
        "component": "procedure_promotion_disposition",
        "disposition": record,
        "canonical_receipt": canonical_receipt,
        "write_status": write_status,
        "idempotent_replay": idempotent_replay,
    })
}

async fn persist_procedure_disposition(
    state: &McpState,
    context: AuthenticatedRequestContext,
    idempotency_key: &str,
    record: CanonicalProcedurePromotionDisposition,
) -> Result<Value> {
    let (receipt, status) = write_canonical_observation(
        state,
        context,
        record.project_id,
        Some(record.task_id),
        CanonicalReceiptKind::ProcedurePromotionDisposition,
        idempotency_key,
        &record,
    )
    .await?;
    Ok(procedure_disposition_response(
        &record,
        &receipt,
        Some(status),
        matches!(status, WriteStatus::IdempotentReplay),
    ))
}

async fn dispatch_procedure_candidate_disposition(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    state.ensure_schema().await?;
    let input: ProcedureCandidateDispositionToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse procedure task_id")?;
    validate_broker_text("idempotency_key", &input.idempotency_key, 256)?;
    let task = require_l11_task(state, project_id, task_id, input.expected_revision).await?;
    let (pattern, pattern_sha256, pattern_observation_ref, pattern_receipt) =
        resolve_exact_procedure_pattern(state, project_id, task_id, &input.pattern_ref).await?;
    let candidate_record =
        resolve_procedure_candidate(state, project_id, task_id, &input.candidate_ref).await?;
    let candidate = &candidate_record.receipt_body;
    if candidate.task_revision != input.expected_revision
        || candidate.pattern_ref != input.pattern_ref
        || candidate.pattern_observation_ref != pattern_observation_ref
        || candidate.pattern_receipt != pattern_receipt
        || candidate.pattern_sha256 != pattern_sha256
    {
        anyhow::bail!("procedure candidate does not match current task revision or exact pattern");
    }
    validate_procedure_candidate_source_refs(&task, &pattern, &candidate.candidate_skill)?;

    let (validated_holdout_evidence_refs, validated_negative_transfer_refs) =
        validate_procedure_disposition_evidence(state, &task, &input).await?;
    let input_fingerprint = procedure_disposition_fingerprint(
        &input,
        &task,
        &pattern_sha256,
        &pattern_observation_ref,
        &pattern_receipt,
        &candidate_record,
    )?;
    let write_id = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::ProcedurePromotionDisposition,
        &input.idempotency_key,
    );
    if let Some(existing) = state
        .store
        .canonical_record_by_write_id::<CanonicalProcedurePromotionDisposition>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ProcedurePromotionDisposition.as_str()],
            write_id,
        )
        .await?
    {
        if existing.receipt_body.input_fingerprint != input_fingerprint {
            anyhow::bail!(
                "procedure disposition idempotency key conflicts with another exact intent"
            );
        }
        return Ok(procedure_disposition_response(
            &existing.receipt_body,
            &existing.canonical_receipt,
            None,
            true,
        ));
    }

    let (lifecycle_record, promotion_outcome, pattern_disposition, not_ready_reasons) =
        evaluate_procedure_disposition(
            &pattern,
            &candidate.candidate_skill,
            &validated_holdout_evidence_refs,
            &validated_negative_transfer_refs,
            !input.holdout_evidence.is_empty(),
        )?;
    let disposition_hash = blake3::hash(input_fingerprint.as_bytes()).to_hex();
    let record = CanonicalProcedurePromotionDisposition {
        schema_version: "eliot-procedure-promotion-disposition-v1".to_owned(),
        disposition_id: format!("procedure-disposition-{disposition_hash}"),
        project_id,
        task_id,
        task_revision: input.expected_revision,
        pattern_ref: input.pattern_ref,
        pattern_observation_ref,
        pattern_receipt,
        pattern_sha256,
        candidate_ref: input.candidate_ref,
        candidate_receipt: candidate_record.canonical_receipt,
        candidate_sha256: candidate.candidate_sha256.clone(),
        holdout_evidence: input.holdout_evidence,
        validated_holdout_evidence_refs,
        negative_transfer_refs: input.negative_transfer_refs,
        validated_negative_transfer_refs,
        unresolved_evidence_refs: Vec::new(),
        lifecycle_record,
        promotion_outcome,
        pattern_disposition,
        not_ready_reasons,
        input_fingerprint,
        candidate_only: true,
        activation_applied: false,
        created_at: time::OffsetDateTime::now_utc(),
    };
    persist_procedure_disposition(state, context, &input.idempotency_key, record).await
}

#[allow(clippy::too_many_lines)]
async fn dispatch_operator_command(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    let input: OperatorCommandToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse operator task_id")?;
    validate_broker_text("idempotency_key", &input.idempotency_key, 256)?;
    let task = state
        .store
        .task_contract_by_id(task_id)
        .await?
        .context("operator task does not exist")?;
    if task.project_id != project_id || task.memory_revision.value() != input.expected_revision {
        anyhow::bail!("operator command has stale or wrong-project task revision");
    }

    let action = serde_json::to_value(&input.command)?
        .get("command")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_owned();
    validate_operator_command_payload(&input.command)?;
    let mut reasons = Vec::new();
    let mut canonical_receipt = None;
    let mut preview = None;
    let mut outcome = "rejected".to_owned();
    let accepted = match &input.command {
        OperatorCommand::SelectTask { task_id: selected } => *selected == task_id,
        OperatorCommand::CreateAutonomyRun { contract } => {
            if contract.project_id != project_id || contract.root_task_id != task_id {
                anyhow::bail!("operator autonomy contract scope differs from the selected task");
            }
            let result =
                dispatch_autonomy_contract_write(state, context, json!({"contract": contract}))
                    .await?;
            canonical_receipt = serde_json::from_value(result["canonical_receipt"].clone())?;
            "autonomy_contract_created".clone_into(&mut outcome);
            true
        }
        OperatorCommand::PreviewAutonomyEdit {
            autonomy_run_id,
            proposed_contract,
        } => {
            let current =
                load_autonomy_contract(state, project_id, task_id, autonomy_run_id).await?;
            if current.state != AutonomyRunState::Draft {
                anyhow::bail!("only a Draft autonomy contract can be edited");
            }
            if proposed_contract.autonomy_run_id != *autonomy_run_id
                || proposed_contract.project_id != project_id
                || proposed_contract.root_task_id != task_id
                || proposed_contract.state != AutonomyRunState::Draft
                || proposed_contract.state_revision != current.state_revision
            {
                anyhow::bail!(
                    "proposed autonomy edit changes immutable identity or revision fields"
                );
            }
            AutonomyRunService::validate_contract(proposed_contract)?;
            let current_value = serde_json::to_value(&current)?;
            let proposed_value = serde_json::to_value(proposed_contract)?;
            let changed_fields = current_value
                .as_object()
                .into_iter()
                .flatten()
                .filter(|(name, value)| proposed_value.get(*name) != Some(*value))
                .map(|(name, _)| name.clone())
                .collect::<Vec<_>>();
            preview = Some(json!({
                "kind": "autonomy_contract_edit_preview",
                "current": current_value,
                "proposed": proposed_value,
                "changed_fields": changed_fields,
                "mutation_executed": false,
                "next_step": "create a replacement Draft contract through its dedicated authority or keep the immutable current contract"
            }));
            "validated_preview".clone_into(&mut outcome);
            true
        }
        OperatorCommand::StartRun { autonomy_run_id } => {
            let contract =
                load_autonomy_contract(state, project_id, task_id, autonomy_run_id).await?;
            if contract.state == AutonomyRunState::Draft {
                let ready_key = format!("{}:ready", input.idempotency_key);
                let _ = apply_autonomy_transition(
                    state,
                    context,
                    project_id,
                    task_id,
                    autonomy_run_id,
                    Some(contract.state_revision),
                    AutonomyTransitionRequest {
                        target: AutonomyRunState::Ready,
                        reason: "operator validated bounded run".to_owned(),
                        risk_tier: "R1".to_owned(),
                        approval: None,
                        verifier_refs: Vec::new(),
                    },
                    Some(&ready_key),
                )
                .await?;
            }
            let primary_key = format!("{}:primary", input.idempotency_key);
            let result = apply_autonomy_transition(
                state,
                context,
                project_id,
                task_id,
                autonomy_run_id,
                None,
                AutonomyTransitionRequest {
                    target: AutonomyRunState::Running,
                    reason: "operator start".to_owned(),
                    risk_tier: "R1".to_owned(),
                    approval: None,
                    verifier_refs: Vec::new(),
                },
                Some(&primary_key),
            )
            .await?;
            canonical_receipt =
                serde_json::from_value(result["transition"]["canonical_receipt"].clone())?;
            true
        }
        OperatorCommand::PauseRun {
            autonomy_run_id,
            reason,
        }
        | OperatorCommand::CancelRun {
            autonomy_run_id,
            reason,
        } => {
            let target = if matches!(&input.command, OperatorCommand::PauseRun { .. }) {
                AutonomyRunState::PausedByOperator
            } else {
                AutonomyRunState::Cancelled
            };
            let primary_key = format!("{}:primary", input.idempotency_key);
            let result = apply_autonomy_transition(
                state,
                context,
                project_id,
                task_id,
                autonomy_run_id,
                None,
                AutonomyTransitionRequest {
                    target,
                    reason: reason.clone(),
                    risk_tier: "R1".to_owned(),
                    approval: None,
                    verifier_refs: Vec::new(),
                },
                Some(&primary_key),
            )
            .await?;
            canonical_receipt =
                serde_json::from_value(result["transition"]["canonical_receipt"].clone())?;
            true
        }
        OperatorCommand::ResumeRun { autonomy_run_id } => {
            let primary_key = format!("{}:primary", input.idempotency_key);
            let result = apply_autonomy_transition(
                state,
                context,
                project_id,
                task_id,
                autonomy_run_id,
                None,
                AutonomyTransitionRequest {
                    target: AutonomyRunState::Running,
                    reason: "operator resume".to_owned(),
                    risk_tier: "R1".to_owned(),
                    approval: None,
                    verifier_refs: Vec::new(),
                },
                Some(&primary_key),
            )
            .await?;
            canonical_receipt =
                serde_json::from_value(result["transition"]["canonical_receipt"].clone())?;
            true
        }
        OperatorCommand::ContestMemory {
            task_id: selected,
            memory_handle,
            evidence_refs,
        } => {
            if *selected == task_id {
                canonical_receipt = Some(
                    persist_operator_minority_pressure(
                        state,
                        context,
                        project_id,
                        task_id,
                        memory_handle,
                        evidence_refs.clone(),
                        &input.idempotency_key,
                    )
                    .await?,
                );
                true
            } else {
                false
            }
        }
        OperatorCommand::SuppressMemory {
            task_id: selected,
            memory_handle,
            reason,
        }
        | OperatorCommand::ArchiveMemory {
            task_id: selected,
            memory_handle,
            reason,
        } => {
            if *selected == task_id {
                let (operator, forgetting_reason) =
                    if matches!(&input.command, OperatorCommand::SuppressMemory { .. }) {
                        (ForgettingOperator::Suppress, ForgettingReason::WrongScope)
                    } else {
                        (ForgettingOperator::Archive, ForgettingReason::LowUtility)
                    };
                canonical_receipt = Some(
                    persist_operator_lifecycle_transition(
                        state,
                        context,
                        project_id,
                        task_id,
                        memory_handle,
                        operator,
                        forgetting_reason,
                        OperatorLifecycleBinding::unbound(vec![reason.clone()]),
                        &input.idempotency_key,
                    )
                    .await?,
                );
                true
            } else {
                false
            }
        }
        OperatorCommand::RestoreMemory {
            task_id: selected,
            memory_handle,
            evidence_refs,
        } => {
            if *selected == task_id {
                canonical_receipt = Some(
                    persist_operator_lifecycle_transition(
                        state,
                        context,
                        project_id,
                        task_id,
                        memory_handle,
                        ForgettingOperator::Restore,
                        ForgettingReason::WrongScope,
                        OperatorLifecycleBinding::unbound(evidence_refs.clone()),
                        &input.idempotency_key,
                    )
                    .await?,
                );
                true
            } else {
                false
            }
        }
        OperatorCommand::ReviewCandidate {
            task_id: selected,
            candidate_ref,
            disposition,
            evidence_refs,
        } => {
            if *selected != task_id {
                anyhow::bail!("operator candidate task differs from the selected canonical task");
            }
            let (receipt, candidate_outcome) = execute_operator_candidate_review(
                state,
                context,
                &task,
                candidate_ref,
                disposition,
                evidence_refs,
                &input.idempotency_key,
            )
            .await?;
            canonical_receipt = Some(receipt);
            candidate_outcome.clone_into(&mut outcome);
            true
        }
        OperatorCommand::DispositionAgentResult {
            result_id,
            disposition,
        } => {
            let kind = match disposition.trim().to_ascii_lowercase().as_str() {
                "reject" | "rejected" => AgentResultDispositionKind::Rejected,
                "probe" | "probe_requested" => AgentResultDispositionKind::ProbeRequested,
                "accept" | "accepted" => anyhow::bail!(
                    "HumanOperator acceptance must use the governed controller finalization path"
                ),
                other => anyhow::bail!(
                    "unsupported HumanOperator agent-result disposition: {other}; expected rejected or probe_requested"
                ),
            };
            let mut broker_state = delegation_runtime::load_state(&state.root)?;
            let invocation = broker_state
                .agent_results
                .iter()
                .find(|result| result.result_id == *result_id)
                .and_then(|result| {
                    broker_state
                        .agent_invocations
                        .iter()
                        .find(|request| request.invocation_id == result.invocation_id)
                })
                .context("operator agent-result disposition lacks its invocation authority")?;
            if invocation.project_id != project_id || invocation.task_id != task_id {
                anyhow::bail!("operator agent-result disposition has wrong project/task scope");
            }
            let authority_session_id = AgentSessionId::from_uuid(context.session_id.as_uuid());
            let normalized_disposition = disposition.trim().to_ascii_lowercase();
            let disposition_reason = format!(
                "HumanOperator selected {normalized_disposition} through the typed Eliot Operator command"
            );
            let disposition_evidence = vec![format!(
                "eliot/task/{task_id}@{}",
                task.memory_revision.value()
            )];
            let mut record = HostBrokerService.disposition_result_as_human_operator(
                &mut broker_state,
                authority_session_id,
                result_id,
                kind,
                disposition_reason,
                disposition_evidence,
                input.idempotency_key.clone(),
            )?;
            if record.canonical_receipt.is_none() {
                let (receipt, _) = write_canonical_observation(
                    state,
                    context,
                    project_id,
                    Some(task_id),
                    CanonicalReceiptKind::AgentResultDisposition,
                    &format!(
                        "operator-agent-result-disposition:{}",
                        input.idempotency_key
                    ),
                    &record,
                )
                .await?;
                record.canonical_receipt = Some(receipt);
                let stored = broker_state
                    .agent_result_dispositions
                    .iter_mut()
                    .find(|item| item.disposition_id == record.disposition_id)
                    .context(
                        "operator AgentResultDisposition disappeared before receipt binding",
                    )?;
                *stored = record.clone();
            }
            delegation_runtime::save_host_broker_state(&state.root, &broker_state)?;
            canonical_receipt = record.canonical_receipt.clone();
            "agent_result_disposition_committed".clone_into(&mut outcome);
            true
        }
        OperatorCommand::RequestRevalidation {
            task_id: selected,
            memory_handle,
        } if *selected == task_id => {
            canonical_receipt = Some(
                persist_operator_control_request(
                    state,
                    context,
                    OperatorControlRequestDraft {
                        project_id,
                        task_id,
                        operation: "request_revalidation",
                        target_ref: memory_handle,
                        disposition: "requested",
                        exact_action_hash: None,
                        reason_or_evidence_refs: Vec::new(),
                        idempotency_key: &input.idempotency_key,
                    },
                )
                .await?,
            );
            "revalidation_request_recorded".clone_into(&mut outcome);
            true
        }
        OperatorCommand::RefreshPacket { task_id: selected } if *selected == task_id => {
            let candidate_handles = latest_task_packet(state, task_id)?
                .map(|packet| packet.exact_handles)
                .unwrap_or_default();
            let packet = dispatch_compile_packet_l3(
                state,
                json!({
                    "project_id": project_id,
                    "task_id": task_id.to_string(),
                    "goal": task.title.clone(),
                    "candidate_handles": candidate_handles,
                    "max_tokens": 4096
                }),
            )
            .await?;
            let packet_id = packet
                .get("packet_id")
                .and_then(Value::as_str)
                .context("refreshed packet has no packet_id")?
                .to_owned();
            let packet_hash = format!(
                "blake3:{}",
                blake3::hash(&serde_json::to_vec(&packet)?).to_hex()
            );
            canonical_receipt = Some(
                persist_operator_control_request(
                    state,
                    context,
                    OperatorControlRequestDraft {
                        project_id,
                        task_id,
                        operation: "refresh_packet",
                        target_ref: &packet_id,
                        disposition: "executed",
                        exact_action_hash: Some(packet_hash.clone()),
                        reason_or_evidence_refs: vec![packet_hash],
                        idempotency_key: &input.idempotency_key,
                    },
                )
                .await?,
            );
            preview = Some(packet);
            "packet_refreshed".clone_into(&mut outcome);
            true
        }
        OperatorCommand::TriggerBackupValidation { task_id: selected } if *selected == task_id => {
            let report = BackupService::new(&state.root)
                .run(eliot_types::BackupKind::LogicalExport, true)?;
            preview = Some(serde_json::to_value(&report)?);
            "validated_preview".clone_into(&mut outcome);
            true
        }
        OperatorCommand::RequestImportPreview {
            task_id: selected,
            source_ref,
        } if *selected == task_id => {
            let import_preview = ImportService::new(&state.root).preview(
                std::path::Path::new(source_ref),
                &format!("operator-runtime:{}", state.runtime_id),
            )?;
            preview = Some(serde_json::to_value(&import_preview)?);
            "validated_preview".clone_into(&mut outcome);
            true
        }
        OperatorCommand::FinishGapPreview { task_id: selected } if *selected == task_id => {
            let unsatisfied_acceptance = task
                .acceptance_items
                .iter()
                .filter(|item| !item.satisfied)
                .map(|item| item.item_id.clone())
                .collect::<Vec<_>>();
            let can_request_completion =
                unsatisfied_acceptance.is_empty() && !task.verification_ids.is_empty();
            preview = Some(json!({
                "kind": "finish_gap_preview",
                "task_id": task_id,
                "memory_revision": task.memory_revision,
                "unsatisfied_acceptance": unsatisfied_acceptance,
                "verification_ids": task.verification_ids.clone(),
                "can_request_completion": can_request_completion,
                "mutation_executed": false
            }));
            "validated_preview".clone_into(&mut outcome);
            true
        }
        OperatorCommand::GrantApproval {
            approval_id,
            exact_action_hash,
        } => {
            if approval_id.starts_with("autonomy-approval:") {
                let result = execute_operator_autonomy_approval_decision(
                    state,
                    context,
                    OperatorAutonomyApprovalDecision {
                        project_id,
                        task_id,
                        approval_id,
                        exact_action_hash,
                        decision: AutonomyApprovalDecisionKind::Granted,
                        reason: "HumanOperator granted the exact action through Eliot Operator",
                        idempotency_key: &input.idempotency_key,
                    },
                )
                .await?;
                let decision_accepted = result["accepted"].as_bool().unwrap_or(false);
                if decision_accepted {
                    canonical_receipt =
                        Some(serde_json::from_value(result["canonical_receipt"].clone())?);
                    "autonomy_approval_granted".clone_into(&mut outcome);
                } else {
                    reasons.push(
                        result["reason"]
                            .as_str()
                            .unwrap_or("canonical autonomy approval grant was denied")
                            .to_owned(),
                    );
                }
                preview = Some(result);
                decision_accepted
            } else {
                canonical_receipt = Some(
                    persist_operator_control_request(
                        state,
                        context,
                        OperatorControlRequestDraft {
                            project_id,
                            task_id,
                            operation: "grant_approval",
                            target_ref: approval_id,
                            disposition: "unsupported_approval_request_only",
                            exact_action_hash: Some(exact_action_hash.clone()),
                            reason_or_evidence_refs: Vec::new(),
                            idempotency_key: &input.idempotency_key,
                        },
                    )
                    .await?,
                );
                reasons.push(
                    "unsupported approval class recorded as request-only; no approval authority changed"
                        .to_owned(),
                );
                "unsupported_approval_request_recorded".clone_into(&mut outcome);
                true
            }
        }
        OperatorCommand::DenyApproval {
            approval_id,
            exact_action_hash,
            reason,
        } => {
            if approval_id.starts_with("autonomy-approval:") {
                let result = execute_operator_autonomy_approval_decision(
                    state,
                    context,
                    OperatorAutonomyApprovalDecision {
                        project_id,
                        task_id,
                        approval_id,
                        exact_action_hash,
                        decision: AutonomyApprovalDecisionKind::Denied,
                        reason,
                        idempotency_key: &input.idempotency_key,
                    },
                )
                .await?;
                let decision_accepted = result["accepted"].as_bool().unwrap_or(false);
                if decision_accepted {
                    canonical_receipt =
                        Some(serde_json::from_value(result["canonical_receipt"].clone())?);
                    "autonomy_approval_denied".clone_into(&mut outcome);
                } else {
                    reasons.push(
                        result["reason"]
                            .as_str()
                            .unwrap_or("canonical autonomy approval denial was rejected")
                            .to_owned(),
                    );
                }
                preview = Some(result);
                decision_accepted
            } else {
                canonical_receipt = Some(
                    persist_operator_control_request(
                        state,
                        context,
                        OperatorControlRequestDraft {
                            project_id,
                            task_id,
                            operation: "deny_approval",
                            target_ref: approval_id,
                            disposition: "unsupported_approval_request_only",
                            exact_action_hash: Some(exact_action_hash.clone()),
                            reason_or_evidence_refs: vec![reason.clone()],
                            idempotency_key: &input.idempotency_key,
                        },
                    )
                    .await?,
                );
                reasons.push(
                    "unsupported approval class recorded as request-only; no approval authority changed"
                        .to_owned(),
                );
                "unsupported_approval_request_recorded".clone_into(&mut outcome);
                true
            }
        }
        OperatorCommand::RequestRevalidation { .. }
        | OperatorCommand::RefreshPacket { .. }
        | OperatorCommand::TriggerBackupValidation { .. }
        | OperatorCommand::RequestImportPreview { .. }
        | OperatorCommand::FinishGapPreview { .. } => {
            reasons.push("command target does not match the canonical task".to_owned());
            false
        }
    };
    if !accepted && reasons.is_empty() {
        reasons.push("command target does not match the canonical task".to_owned());
    }
    let executed = canonical_receipt.is_some();
    if outcome == "rejected" && accepted {
        outcome = if executed {
            "canonical_mutation_committed".to_owned()
        } else if preview.is_some() {
            "validated_preview".to_owned()
        } else {
            "selection_applied".to_owned()
        };
    }
    serde_json::to_value(OperatorCommandReceipt {
        command_id: format!(
            "operator-command:{}",
            blake3::hash(input.idempotency_key.as_bytes())
        ),
        accepted,
        executed,
        outcome,
        task_id: Some(task_id),
        action,
        revision: Some(task.memory_revision),
        reasons,
        canonical_receipt,
        preview,
        generated_at: time::OffsetDateTime::now_utc(),
    })
    .map_err(Into::into)
}

fn validate_operator_command_payload(command: &OperatorCommand) -> Result<()> {
    match command {
        OperatorCommand::PauseRun { reason, .. }
        | OperatorCommand::CancelRun { reason, .. }
        | OperatorCommand::SuppressMemory { reason, .. }
        | OperatorCommand::ArchiveMemory { reason, .. }
        | OperatorCommand::DenyApproval { reason, .. }
            if reason.trim().is_empty() =>
        {
            anyhow::bail!("operator command reason must not be empty");
        }
        OperatorCommand::ContestMemory { evidence_refs, .. }
        | OperatorCommand::RestoreMemory { evidence_refs, .. }
            if evidence_refs.is_empty() =>
        {
            anyhow::bail!("operator memory command requires evidence_refs");
        }
        OperatorCommand::ReviewCandidate {
            disposition,
            evidence_refs,
            ..
        } => {
            if evidence_refs.is_empty() || evidence_refs.iter().any(|value| value.trim().is_empty())
            {
                anyhow::bail!("operator candidate disposition requires non-empty evidence_refs");
            }
            if !matches!(
                disposition.as_str(),
                "promote" | "reject" | "demote" | "archive"
            ) {
                anyhow::bail!("unsupported operator candidate disposition");
            }
        }
        OperatorCommand::GrantApproval {
            approval_id,
            exact_action_hash,
        }
        | OperatorCommand::DenyApproval {
            approval_id,
            exact_action_hash,
            ..
        } if approval_id.trim().is_empty() || exact_action_hash.trim().is_empty() => {
            anyhow::bail!("operator approval requires canonical id and exact action hash");
        }
        OperatorCommand::RequestImportPreview { source_ref, .. }
            if source_ref.trim().is_empty() =>
        {
            anyhow::bail!("operator import preview requires a source reference");
        }
        OperatorCommand::DispositionAgentResult { disposition, .. }
            if disposition.trim().is_empty() =>
        {
            anyhow::bail!("operator agent-result disposition must not be empty");
        }
        _ => {}
    }
    Ok(())
}

async fn resolve_governed_packet_git_scope(
    input: &CompilePacketL3Request,
    task: Option<&TaskContract>,
    codecortex_reports: &[CodeCortexReport],
) -> Result<Option<eliot_types::memory::GovernedGitScope>> {
    let Some(provenance) = task
        .and_then(|task| task.action_provenance.as_ref())
        .filter(|provenance| provenance.source_scope.kind == "git_worktree")
    else {
        return Ok(None);
    };
    let report = codecortex_reports
        .iter()
        .rev()
        .find(|report| report.task == input.task_id)
        .context("governed Git-scoped packet requires a task-matched CodeCortex report")?;
    let expected_worktree = provenance
        .source_scope
        .worktree_ref
        .as_deref()
        .context("governed Git-scoped task has no worktree identity")?;
    let report_root = tokio::fs::canonicalize(&report.repo_root).await?;
    let expected_root = tokio::fs::canonicalize(expected_worktree).await?;
    if report_root != expected_root {
        anyhow::bail!("CodeCortex report worktree differs from canonical action provenance");
    }
    let scope = resolve_packet_git_scope(&report_root, input.project_id).await?;
    if report.git_head.as_deref() != Some(scope.commit.as_str()) || report.dirty == scope.clean {
        anyhow::bail!("task-matched CodeCortex report is stale for the resolved Git scope");
    }
    Ok(Some(scope))
}

async fn enrich_packet_with_task(
    state: &McpState,
    value: &mut Value,
    task: &TaskContract,
) -> Result<()> {
    let Value::Object(object) = value else {
        return Ok(());
    };
    let refs = canonical_packet_refs(state, task).await?;
    let current_receipt = state
        .store
        .write_receipt_by_id(&task.write_id)
        .await?
        .context("current TaskContract WriteReceipt does not resolve")?;
    object.insert("task_contract".to_owned(), serde_json::to_value(task)?);
    object.insert(
        "task_truth_status".to_owned(),
        Value::String("current_canonical".to_owned()),
    );
    object.insert(
        "task_revision_fence".to_owned(),
        serde_json::to_value(task.memory_revision)?,
    );
    object.insert(
        "packet_revision_fence".to_owned(),
        serde_json::to_value(refs.packet_revision_fence)?,
    );
    object.insert("packet_id".to_owned(), Value::String(refs.packet_id));
    object.insert(
        "task_contract_ref".to_owned(),
        Value::String(refs.task_contract_ref.clone()),
    );
    object.insert(
        "current_truth_refs".to_owned(),
        json!([refs.task_contract_ref]),
    );
    object.insert(
        "exact_evidence_refs".to_owned(),
        json!([current_receipt.receipt_id]),
    );
    object.insert(
        "negative_memory_check_ref".to_owned(),
        Value::String(refs.negative_memory_check_ref),
    );
    object.insert(
        "negative_stale_exclusions".to_owned(),
        json!(["candidate observations are not verifier authority"]),
    );
    object.insert(
        "registered_verifiers".to_owned(),
        Value::Array(
            RegisteredTaskVerifier::ALL
                .into_iter()
                .map(RegisteredTaskVerifier::descriptor)
                .collect(),
        ),
    );
    Ok(())
}

