fn write_metrics_mcp_report<T>(
    state: &McpState,
    report_dir: &str,
    title: &str,
    value: &T,
) -> Result<()>
where
    T: serde::Serialize,
{
    write_json_report(
        &state
            .root
            .join("reports")
            .join(report_dir)
            .join("latest.json"),
        value,
    )?;
    write_markdown_report(
        &state
            .root
            .join("reports")
            .join(report_dir)
            .join("latest.md"),
        &typed_report_markdown(title, value)?,
    )
}

