fn parse_eval_family(value: &str) -> Result<EvalFamily> {
    match normalized_cli_value(value).as_str() {
        "understand" => Ok(EvalFamily::Understand),
        "hallucination" => Ok(EvalFamily::Hallucination),
        "negative" => Ok(EvalFamily::Negative),
        "done" => Ok(EvalFamily::Done),
        "context" => Ok(EvalFamily::Context),
        "compaction" => Ok(EvalFamily::Compaction),
        "tool" => Ok(EvalFamily::Tool),
        "memory" => Ok(EvalFamily::Memory),
        "forget" => Ok(EvalFamily::Forget),
        "dream" => Ok(EvalFamily::Dream),
        "skill" => Ok(EvalFamily::Skill),
        "trace" => Ok(EvalFamily::Trace),
        "bench" => Ok(EvalFamily::Bench),
        "ale" => Ok(EvalFamily::Ale),
        "provider" => Ok(EvalFamily::Provider),
        "future" => Ok(EvalFamily::Future),
        other => anyhow::bail!("unknown eval family: {other}"),
    }
}

fn l11_idempotency_key(base: &str, suffix: &str) -> Result<String> {
    let base = base.trim();
    if base.is_empty() {
        anyhow::bail!("L11 idempotency_key must not be empty");
    }
    Ok(format!("l11:{base}:{suffix}"))
}

fn l11_fingerprint_marker(fingerprint: &str) -> String {
    format!("mcp_input_fingerprint={fingerprint}")
}

fn trace_ref_value<'a>(value: &'a str, category: &str) -> Result<&'a str> {
    let value = value.trim();
    let reference = value
        .strip_prefix(category)
        .and_then(|suffix| {
            suffix
                .strip_prefix(':')
                .or_else(|| suffix.strip_prefix('='))
        })
        .filter(|reference| !reference.trim().is_empty())
        .with_context(|| format!("{category} must use {category}:<canonical-ref>"))?;
    Ok(reference)
}

async fn require_l11_task(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    expected_revision: u64,
) -> Result<TaskContract> {
    let task = require_task(state, project_id, task_id).await?;
    if task.memory_revision != MemoryRevision::new(expected_revision) {
        anyhow::bail!(
            "stale L11 task revision: expected {expected_revision}, current {}",
            task.memory_revision.value()
        );
    }
    Ok(task)
}

async fn l11_trace_records(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
) -> Result<Vec<CanonicalRecord<CanonicalTraceCompletenessContract>>> {
    Ok(state
        .store
        .replay_view(project_id, Some(task_id), 128)
        .await?
        .trace_contracts)
}

async fn require_registered_trace(
    state: &McpState,
    task: &TaskContract,
    trace_ref: &str,
) -> Result<CanonicalRecord<CanonicalTraceCompletenessContract>> {
    let record = state
        .store
        .canonical_trace_by_trace_ref(task.project_id, task.task_id, trace_ref)
        .await?
        .with_context(|| format!("canonical complete trace is not registered: {trace_ref}"))?;
    revalidate_canonical_trace(state, task, &record.receipt_body).await?;
    Ok(record)
}

async fn canonical_source_binding(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    write_id: WriteId,
    source_content_hash: String,
    label: &str,
) -> Result<CanonicalTraceReceiptBinding> {
    let receipt = state
        .store
        .write_receipt_by_id(&write_id)
        .await?
        .with_context(|| format!("{label} has no canonical write receipt"))?;
    if receipt.project_id != project_id
        || receipt.task_id != Some(task_id)
        || !matches!(
            receipt.status,
            WriteStatus::Committed | WriteStatus::IdempotentReplay
        )
        || !is_canonical_hash(&receipt.input_hash)
        || !is_canonical_hash(&source_content_hash)
    {
        anyhow::bail!("{label} canonical receipt scope, status, or hash is invalid");
    }
    Ok(CanonicalTraceReceiptBinding {
        receipt: WriteReceiptRef {
            receipt_id: receipt.receipt_id,
            write_id: receipt.write_id,
        },
        command_kind: receipt.command_kind,
        input_hash: receipt.input_hash,
        source_content_hash,
    })
}

async fn resolve_canonical_trace_evidence(
    state: &McpState,
    input: &TraceCompletenessToolInput,
    task: &TaskContract,
) -> Result<Vec<CanonicalTraceEvidence>> {
    let (observation_id, verification_id, artifact) = validate_trace_source_refs(input, task)?;
    let observation_write_id = WriteId::from_str(&observation_id)
        .context("actual observation id must be its canonical write id")?;
    let verifier_write_id = WriteId::from_uuid(verification_id.as_uuid());
    let observation = state
        .store
        .tool_observation_by_id(&observation_id)
        .await?
        .context("actual observation record is not canonical")?;
    let verification = state
        .store
        .verification_run_by_id(verification_id)
        .await?
        .context("registered verifier run is not canonical")?;
    if verification.result != VerificationResult::Passed {
        anyhow::bail!("trace registration requires a passed canonical verifier run");
    }
    let task_binding = canonical_source_binding(
        state,
        task.project_id,
        task.task_id,
        task.write_id,
        canonical_struct_hash(task)?,
        "task contract",
    )
    .await?;
    let observation_binding = canonical_source_binding(
        state,
        task.project_id,
        task.task_id,
        observation_write_id,
        canonical_struct_hash(&observation)?,
        "actual observation",
    )
    .await?;
    let verifier_binding = canonical_source_binding(
        state,
        task.project_id,
        task.task_id,
        verifier_write_id,
        canonical_struct_hash(&verification)?,
        "verifier run",
    )
    .await?;
    let task_ref = format!("task_contract:{}", task.task_id);
    let actual_ref = format!("actual_observation:{observation_id}");
    let verifier_ref = format!("verifier_run:{verification_id}");
    let receipt_sources = [
        (
            CanonicalTraceEvidenceKind::TaskContract,
            task_ref.clone(),
            task_binding.clone(),
        ),
        (
            CanonicalTraceEvidenceKind::ActualObservation,
            actual_ref.clone(),
            observation_binding.clone(),
        ),
        (
            CanonicalTraceEvidenceKind::VerifierRun,
            verifier_ref.clone(),
            verifier_binding.clone(),
        ),
    ];
    let mut evidence = canonical_receipt_trace_evidence(task, &receipt_sources)?;
    let input_refs = vec![task_ref, actual_ref, verifier_ref];
    let input_hashes = vec![
        task_binding.input_hash,
        observation_binding.input_hash,
        verifier_binding.input_hash,
    ];
    for (kind, reference) in canonical_derived_trace_references(
        task,
        &observation_id,
        verification_id,
        &artifact,
        state.profile.as_str(),
    ) {
        evidence.push(TraceCompletenessService::derivation_evidence(
            kind,
            task.project_id,
            task.task_id,
            task.memory_revision,
            reference,
            "eliot-l11-canonical-resolution-v1".to_owned(),
            input_refs.clone(),
            input_hashes.clone(),
            TaintClass::LocalVerified,
        )?);
    }
    Ok(evidence)
}

fn canonical_receipt_trace_evidence(
    task: &TaskContract,
    sources: &[(
        CanonicalTraceEvidenceKind,
        String,
        CanonicalTraceReceiptBinding,
    )],
) -> Result<Vec<CanonicalTraceEvidence>> {
    sources
        .iter()
        .map(|(kind, reference, binding)| {
            TraceCompletenessService::receipt_evidence(
                *kind,
                task.project_id,
                task.task_id,
                task.memory_revision,
                reference.clone(),
                binding.clone(),
                TaintClass::LocalVerified,
            )
            .map_err(Into::into)
        })
        .collect()
}

async fn revalidate_canonical_trace(
    state: &McpState,
    task: &TaskContract,
    contract: &CanonicalTraceCompletenessContract,
) -> Result<()> {
    if contract.project_id != task.project_id
        || contract.task_id != task.task_id
        || contract.source_task_revision != task.memory_revision
    {
        anyhow::bail!("canonical trace is stale or outside the current task scope");
    }
    TraceCompletenessService::validate_canonical_contract(contract)?;
    for evidence in &contract.evidence {
        let CanonicalTraceEvidenceSource::CanonicalReceipt { binding } = &evidence.source else {
            continue;
        };
        let current = current_trace_receipt_binding(state, task, evidence).await?;
        if *binding != current {
            anyhow::bail!("canonical trace receipt binding changed or was fabricated");
        }
    }
    Ok(())
}

async fn current_trace_receipt_binding(
    state: &McpState,
    task: &TaskContract,
    evidence: &CanonicalTraceEvidence,
) -> Result<CanonicalTraceReceiptBinding> {
    match evidence.kind {
        CanonicalTraceEvidenceKind::TaskContract => {
            if evidence.reference != format!("task_contract:{}", task.task_id) {
                anyhow::bail!("task contract evidence reference is not canonical");
            }
            canonical_source_binding(
                state,
                task.project_id,
                task.task_id,
                task.write_id,
                canonical_struct_hash(task)?,
                "task contract",
            )
            .await
        }
        CanonicalTraceEvidenceKind::ActualObservation => {
            let observation_id = trace_ref_value(&evidence.reference, "actual_observation")?;
            if !task
                .observation_ids
                .iter()
                .any(|value| value == observation_id)
            {
                anyhow::bail!("actual observation evidence is no longer attached to the task");
            }
            let observation = state
                .store
                .tool_observation_by_id(observation_id)
                .await?
                .context("actual observation evidence no longer resolves")?;
            canonical_source_binding(
                state,
                task.project_id,
                task.task_id,
                WriteId::from_str(observation_id)?,
                canonical_struct_hash(&observation)?,
                "actual observation",
            )
            .await
        }
        CanonicalTraceEvidenceKind::VerifierRun => {
            let verification_id =
                VerificationId::from_str(trace_ref_value(&evidence.reference, "verifier_run")?)?;
            if !task.verification_ids.contains(&verification_id) {
                anyhow::bail!("verifier evidence is no longer attached to the task");
            }
            let verification = state
                .store
                .verification_run_by_id(verification_id)
                .await?
                .context("verifier evidence no longer resolves")?;
            if verification.result != VerificationResult::Passed {
                anyhow::bail!("canonical verifier evidence is no longer passed");
            }
            canonical_source_binding(
                state,
                task.project_id,
                task.task_id,
                WriteId::from_uuid(verification_id.as_uuid()),
                canonical_struct_hash(&verification)?,
                "verifier run",
            )
            .await
        }
        _ => anyhow::bail!("derived trace evidence cannot carry a canonical receipt binding"),
    }
}

fn is_canonical_hash(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn validate_trace_source_refs(
    input: &TraceCompletenessToolInput,
    task: &TaskContract,
) -> Result<(String, VerificationId, String)> {
    let observation_id =
        trace_ref_value(&input.actual_observation_ref, "actual_observation")?.to_owned();
    if !task
        .observation_ids
        .iter()
        .any(|candidate| candidate == &observation_id)
    {
        anyhow::bail!("actual_observation_ref is not attached to the canonical task");
    }
    let verification_id =
        VerificationId::from_str(trace_ref_value(&input.verifier_run_ref, "verifier_run")?)
            .context("parse verifier_run verification id")?;
    if !task.verification_ids.contains(&verification_id) {
        anyhow::bail!("verifier_run_ref is not attached to the canonical task");
    }
    let artifact = trace_ref_value(&input.artifact_ref, "artifact_ref")?.to_owned();
    let artifact_is_scoped = task.verification_scopes.iter().any(|scope| {
        scope.verification_id == verification_id
            && scope.artifact_refs.iter().any(|candidate| {
                candidate.resource_ref == artifact || candidate.content_hash == artifact
            })
    });
    if !artifact_is_scoped {
        anyhow::bail!("artifact_ref is not covered by the canonical verifier scope");
    }
    if input.source_route.trim().is_empty()
        || input.source_tool.trim().is_empty()
        || input.source_verifier.trim().is_empty()
        || input.outcome.trim().is_empty()
    {
        anyhow::bail!("trace source route, tool, verifier, and outcome must be explicit");
    }
    Ok((observation_id, verification_id, artifact))
}

fn canonical_derived_trace_references(
    task: &TaskContract,
    observation_id: &str,
    verification_id: VerificationId,
    artifact: &str,
    profile: &str,
) -> [(CanonicalTraceEvidenceKind, String); 10] {
    [
        (
            CanonicalTraceEvidenceKind::ContextPacket,
            format!(
                "context_packet:{}:{}",
                task.task_id,
                task.memory_revision.value()
            ),
        ),
        (
            CanonicalTraceEvidenceKind::CurrentTruthRevision,
            format!("current_truth_revision:{}", task.memory_revision.value()),
        ),
        (
            CanonicalTraceEvidenceKind::MemoryExposureSet,
            format!(
                "memory_exposure_set:{}:{}",
                task.task_id,
                task.project_sequence.value()
            ),
        ),
        (
            CanonicalTraceEvidenceKind::AgentToolEvents,
            format!("agent_tool_events:{observation_id}"),
        ),
        (
            CanonicalTraceEvidenceKind::ExpectedObservation,
            format!("expected_observation:verification:{verification_id}:passed"),
        ),
        (
            CanonicalTraceEvidenceKind::ArtifactRef,
            format!("artifact_ref:{artifact}"),
        ),
        (
            CanonicalTraceEvidenceKind::FinishDecision,
            format!("finish_decision:{}:{:?}", task.write_id, task.status),
        ),
        (
            CanonicalTraceEvidenceKind::PolicySnapshot,
            "policy_snapshot:eliot-l11-canonical-v1".to_owned(),
        ),
        (
            CanonicalTraceEvidenceKind::ModelRoute,
            format!("model_route:{profile}"),
        ),
        (
            CanonicalTraceEvidenceKind::OutcomeAndCost,
            format!("outcome_and_cost:{observation_id}:{verification_id}"),
        ),
    ]
}

async fn dispatch_trace_completeness(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    require_l11_controller_authority(state)?;
    let input: TraceCompletenessToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 trace task_id")?;
    let task = require_l11_task(state, project_id, task_id, input.expected_task_revision).await?;
    let write_key = l11_idempotency_key(&input.idempotency_key, "trace-registration")?;
    let write_id = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::TraceCompletenessContract,
        &write_key,
    );
    if input.trace_ref.trim().is_empty() {
        anyhow::bail!("trace_ref must not be empty");
    }
    let evidence = resolve_canonical_trace_evidence(state, &input, &task).await?;
    let contract = TraceCompletenessService::build_canonical(CanonicalTraceCompletenessInput {
        project_id,
        task_id,
        source_task_revision: task.memory_revision,
        trace_ref: input.trace_ref.clone(),
        evidence,
    })?;
    let by_write = state
        .store
        .canonical_record_by_write_id::<CanonicalTraceCompletenessContract>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::TraceCompletenessContract.as_str()],
            write_id,
        )
        .await?;
    let by_trace = state
        .store
        .canonical_trace_by_trace_ref(project_id, task_id, &contract.trace_ref)
        .await?;
    let existing = match (by_write, by_trace) {
        (Some(by_write), Some(by_trace)) => {
            if by_write.canonical_receipt.write_id != by_trace.canonical_receipt.write_id {
                anyhow::bail!(
                    "trace registration idempotency key and trace_ref resolve to different canonical records"
                );
            }
            Some(by_write)
        }
        (Some(by_write), None) => Some(by_write),
        (None, Some(by_trace)) => Some(by_trace),
        (None, None) => None,
    };
    if let Some(existing) = existing {
        revalidate_canonical_trace(state, &task, &existing.receipt_body).await?;
        if existing.receipt_body != contract {
            anyhow::bail!("trace registration idempotency or trace_ref conflict");
        }
        return Ok(json!({
            "accepted": true,
            "replayed": true,
            "trace": existing.receipt_body,
            "canonical_receipt": existing.canonical_receipt,
            "memory_revision": existing.memory_revision
        }));
    }
    let (receipt, write_status) = write_canonical_observation(
        state,
        context,
        project_id,
        Some(task_id),
        CanonicalReceiptKind::TraceCompletenessContract,
        &write_key,
        &contract,
    )
    .await?;
    let persisted = state
        .store
        .canonical_record_by_write_id::<CanonicalTraceCompletenessContract>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::TraceCompletenessContract.as_str()],
            receipt.write_id,
        )
        .await?
        .context("canonical trace contract was not rehydrated after write")?;
    write_json_report(
        &j0_latest_path(&state.root, "trace-completeness"),
        &contract,
    )?;
    Ok(json!({
        "accepted": true,
        "replayed": false,
        "trace": contract,
        "canonical_receipt": receipt,
        "memory_revision": persisted.memory_revision,
        "write_status": write_status
    }))
}

#[allow(clippy::too_many_lines)]
async fn dispatch_replay_run(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    require_l11_controller_authority(state)?;
    let input: ReplayRunToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 replay task_id")?;
    let task = require_l11_task(state, project_id, task_id, input.expected_task_revision).await?;
    let input_fingerprint = canonical_struct_hash(&input)?;
    let (trace_refs, role) = validate_canonical_replay_request(&input)?;
    let baseline_ref = canonical_struct_hash(&ExperimentalMetaPolicyPayload::ReplayThresholdV1 {
        policy: input.baseline_policy.clone(),
    })?;
    let candidate_ref = canonical_struct_hash(&ExperimentalMetaPolicyPayload::ReplayThresholdV1 {
        policy: input.candidate_policy.clone(),
    })?;
    let set_key = l11_idempotency_key(&input.idempotency_key, "replay-set")?;
    let baseline_key = l11_idempotency_key(&input.idempotency_key, "replay-baseline")?;
    let candidate_key = l11_idempotency_key(&input.idempotency_key, "replay-candidate")?;
    let expected_baseline_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::SealedReplayRun,
        &baseline_key,
    );
    let expected_candidate_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::SealedReplayRun,
        &candidate_key,
    );
    if let Some(existing) = state
        .store
        .canonical_record_by_write_id::<CanonicalReplayExecutionRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::SealedReplayRun.as_str()],
            expected_baseline_write,
        )
        .await?
    {
        let request = AuthoritativeReplayRequest {
            task: &task,
            input: &input,
            input_fingerprint: &input_fingerprint,
            expected_candidate_write,
            baseline: &existing,
            replayed: true,
        };
        return reconcile_authoritative_replay(state, context, &request).await;
    }
    let mut contracts = Vec::with_capacity(trace_refs.len());
    for trace_ref in &trace_refs {
        contracts.push(
            require_registered_trace(state, &task, trace_ref)
                .await?
                .receipt_body,
        );
    }
    let mut cases = Vec::with_capacity(contracts.len());
    let mut snapshots = Vec::with_capacity(contracts.len());
    for contract in &contracts {
        let context_ref =
            canonical_trace_reference(contract, CanonicalTraceEvidenceKind::ContextPacket)?;
        let memory_ref =
            canonical_trace_reference(contract, CanonicalTraceEvidenceKind::MemoryExposureSet)?;
        let policy_ref =
            canonical_trace_reference(contract, CanonicalTraceEvidenceKind::PolicySnapshot)?;
        let artifact_ref =
            canonical_trace_reference(contract, CanonicalTraceEvidenceKind::ArtifactRef)?;
        let case = ReplayCaseService::create(ReplayCaseInput {
            project_id,
            source_task_id: Some(task_id),
            case_kind: input.case_kind.clone(),
            trace_contract_ref: contract.contract_id.clone(),
            input_snapshot_refs: vec![
                context_ref.clone(),
                memory_ref.clone(),
                policy_ref.clone(),
                artifact_ref.clone(),
            ],
        })?;
        snapshots.push(ReplayInputSnapshot {
            snapshot_id: format!("replay-snapshot:{}", contract.evidence_manifest_hash),
            replay_case_id: case.replay_case_id,
            context_packet_ref: Some(context_ref),
            memory_refs: vec![memory_ref],
            skill_refs: Vec::new(),
            policy_refs: vec![policy_ref],
            artifact_refs: vec![artifact_ref],
            created_at: time::OffsetDateTime::now_utc(),
        });
        cases.push(case);
    }
    let set = ReplaySetService::create(ReplaySetInput {
        project_id,
        name: input.set_name.clone(),
        purpose: format!("L11 {} sealed canonical replay", input.set_role),
        cases: cases.iter().map(|case| case.replay_case_id).collect(),
        fixed: true,
        holdout: role == ReplaySetRole::Holdout,
        created_from_refs: contracts
            .iter()
            .map(|contract| contract.contract_id.clone())
            .collect(),
    });
    let sealed = ReplaySealService::seal(ReplaySealInput {
        set,
        role,
        version: input.set_version,
        evaluator_version: input.evaluator_version.clone(),
        context_version: input.sealed_context_version.clone(),
        cases,
        snapshots,
    })?;
    let observations = sealed
        .cases
        .iter()
        .zip(&sealed.snapshots)
        .zip(&contracts)
        .map(
            |((case, snapshot), contract)| CanonicalReplayObservationEvidence {
                replay_case_id: case.case.replay_case_id,
                snapshot_hash: snapshot.content_hash.clone(),
                evidence: contract.evidence.clone(),
            },
        )
        .collect::<Vec<_>>();
    let mut baseline_execution =
        ReplayRunnerService::run_canonical(CanonicalReplayExecutionInput {
            sealed_set: sealed.set.clone(),
            cases: sealed.cases.clone(),
            snapshots: sealed.snapshots.clone(),
            trace_contracts: contracts.clone(),
            observations: observations.clone(),
            baseline_ref: baseline_ref.clone(),
            candidate_ref: baseline_ref.clone(),
            candidate_version: input.baseline_version.clone(),
            mutation_attempt: input.mutation_attempt.clone(),
        })?;
    let candidate_execution = ReplayRunnerService::run_canonical(CanonicalReplayExecutionInput {
        sealed_set: sealed.set.clone(),
        cases: sealed.cases.clone(),
        snapshots: sealed.snapshots.clone(),
        trace_contracts: contracts,
        observations,
        baseline_ref,
        candidate_ref,
        candidate_version: input.candidate_version.clone(),
        mutation_attempt: input.mutation_attempt.clone(),
    })?;
    let expected_set_write_id = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::ReplaySet,
        &set_key,
    );
    let expected_case_write_ids = (0..sealed.cases.len())
        .map(|index| {
            let key = l11_idempotency_key(&input.idempotency_key, &format!("replay-case-{index}"))?;
            Ok(deterministic_canonical_write_id(
                project_id,
                Some(task_id),
                CanonicalReceiptKind::ReplayCase,
                &key,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    let expected_snapshot_write_ids = (0..sealed.snapshots.len())
        .map(|index| {
            let key =
                l11_idempotency_key(&input.idempotency_key, &format!("replay-snapshot-{index}"))?;
            Ok(deterministic_canonical_write_id(
                project_id,
                Some(task_id),
                CanonicalReceiptKind::ReplayInputSnapshot,
                &key,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    baseline_execution.authoritative_replay = Some(Box::new(CanonicalReplayAuthority {
        input_fingerprint: input_fingerprint.clone(),
        sealed_set: sealed.set.clone(),
        cases: sealed.cases.clone(),
        snapshots: sealed.snapshots.clone(),
        candidate_execution: candidate_execution.clone(),
        expected_baseline_write_id: expected_baseline_write,
        expected_candidate_write_id: expected_candidate_write,
        expected_set_write_id,
        expected_case_write_ids,
        expected_snapshot_write_ids,
    }));
    let baseline_receipt = persist_l11_record(
        state,
        context,
        project_id,
        task_id,
        CanonicalReceiptKind::SealedReplayRun,
        &baseline_key,
        &baseline_execution,
    )
    .await?;
    maybe_inject_m2_failure(
        "ELIOT_TEST_M2_REPLAY_FAIL_AFTER_BASELINE",
        &input.idempotency_key,
        "replay baseline primary",
    )?;
    let persisted_baseline = state
        .store
        .canonical_record_by_write_id::<CanonicalReplayExecutionRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::SealedReplayRun.as_str()],
            baseline_receipt.0.write_id,
        )
        .await?
        .context("canonical replay baseline primary was not rehydrated after write")?;
    let request = AuthoritativeReplayRequest {
        task: &task,
        input: &input,
        input_fingerprint: &input_fingerprint,
        expected_candidate_write,
        baseline: &persisted_baseline,
        replayed: false,
    };
    let report = reconcile_authoritative_replay(state, context, &request).await?;
    write_json_report(&j0_latest_path(&state.root, "replay-runs"), &report)?;
    let verdict = ReplayVerdictService::verdict(&candidate_execution.run);
    write_json_report(&j0_latest_path(&state.root, "replay-verdicts"), &verdict)?;
    Ok(report)
}

struct AuthoritativeReplayRequest<'a> {
    task: &'a TaskContract,
    input: &'a ReplayRunToolInput,
    input_fingerprint: &'a str,
    expected_candidate_write: WriteId,
    baseline: &'a CanonicalRecord<CanonicalReplayExecutionRecord>,
    replayed: bool,
}

fn validate_authoritative_replay<'a>(
    request: &'a AuthoritativeReplayRequest<'a>,
) -> Result<&'a CanonicalReplayAuthority> {
    let project_id = request.task.project_id;
    let task_id = request.task.task_id;
    let authority = request
        .baseline
        .receipt_body
        .authoritative_replay
        .as_deref()
        .context("canonical replay baseline has no authoritative aggregate")?;
    let baseline_key = l11_idempotency_key(&request.input.idempotency_key, "replay-baseline")?;
    let set_key = l11_idempotency_key(&request.input.idempotency_key, "replay-set")?;
    let expected_baseline_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::SealedReplayRun,
        &baseline_key,
    );
    let expected_set_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::ReplaySet,
        &set_key,
    );
    let expected_case_writes = (0..authority.cases.len())
        .map(|index| {
            let key = l11_idempotency_key(
                &request.input.idempotency_key,
                &format!("replay-case-{index}"),
            )?;
            Ok(deterministic_canonical_write_id(
                project_id,
                Some(task_id),
                CanonicalReceiptKind::ReplayCase,
                &key,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    let expected_snapshot_writes = (0..authority.snapshots.len())
        .map(|index| {
            let key = l11_idempotency_key(
                &request.input.idempotency_key,
                &format!("replay-snapshot-{index}"),
            )?;
            Ok(deterministic_canonical_write_id(
                project_id,
                Some(task_id),
                CanonicalReceiptKind::ReplayInputSnapshot,
                &key,
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    if authority.input_fingerprint != request.input_fingerprint
        || request.baseline.canonical_receipt.write_id != expected_baseline_write
        || authority.expected_baseline_write_id != expected_baseline_write
        || authority.expected_candidate_write_id != request.expected_candidate_write
        || authority.expected_set_write_id != expected_set_write
        || authority.expected_case_write_ids != expected_case_writes
        || authority.expected_snapshot_write_ids != expected_snapshot_writes
        || authority.candidate_execution.authoritative_replay.is_some()
    {
        anyhow::bail!("replay idempotency key conflicts with the authoritative complete input");
    }
    let resealed = ReplaySealService::seal(ReplaySealInput {
        set: authority.sealed_set.set.clone(),
        role: authority.sealed_set.role,
        version: authority.sealed_set.version,
        evaluator_version: authority.sealed_set.evaluator_version.clone(),
        context_version: authority.sealed_set.context_version.clone(),
        cases: authority
            .cases
            .iter()
            .map(|record| record.case.clone())
            .collect(),
        snapshots: authority
            .snapshots
            .iter()
            .map(|record| record.snapshot.clone())
            .collect(),
    })?;
    if resealed.set != authority.sealed_set
        || resealed.cases != authority.cases
        || resealed.snapshots != authority.snapshots
        || request.baseline.receipt_body.sealed_set_hash != authority.sealed_set.sealed_hash
        || authority.candidate_execution.sealed_set_hash != authority.sealed_set.sealed_hash
    {
        anyhow::bail!("authoritative replay aggregate membership is tampered");
    }
    Ok(authority)
}

async fn reconcile_authoritative_replay(
    state: &McpState,
    context: AuthenticatedRequestContext,
    request: &AuthoritativeReplayRequest<'_>,
) -> Result<Value> {
    let scope = (request.task.project_id, request.task.task_id);
    let authority = validate_authoritative_replay(request)?;
    let candidate_key = l11_idempotency_key(&request.input.idempotency_key, "replay-candidate")?;
    let set_key = l11_idempotency_key(&request.input.idempotency_key, "replay-set")?;
    revalidate_execution_trace_authority(state, request.task, &request.baseline.receipt_body)
        .await?;
    revalidate_execution_trace_authority(state, request.task, &authority.candidate_execution)
        .await?;

    let mut record_receipts = Vec::new();
    record_receipts.push(
        reconcile_l11_record(
            state,
            context,
            scope,
            CanonicalReceiptKind::ReplaySet,
            &set_key,
            &authority.sealed_set,
        )
        .await?,
    );
    for (index, case) in authority.cases.iter().enumerate() {
        let key = l11_idempotency_key(
            &request.input.idempotency_key,
            &format!("replay-case-{index}"),
        )?;
        record_receipts.push(
            reconcile_l11_record(
                state,
                context,
                scope,
                CanonicalReceiptKind::ReplayCase,
                &key,
                case,
            )
            .await?,
        );
    }
    for (index, snapshot) in authority.snapshots.iter().enumerate() {
        let key = l11_idempotency_key(
            &request.input.idempotency_key,
            &format!("replay-snapshot-{index}"),
        )?;
        record_receipts.push(
            reconcile_l11_record(
                state,
                context,
                scope,
                CanonicalReceiptKind::ReplayInputSnapshot,
                &key,
                snapshot,
            )
            .await?,
        );
    }
    let candidate_receipt = reconcile_l11_record(
        state,
        context,
        scope,
        CanonicalReceiptKind::SealedReplayRun,
        &candidate_key,
        &authority.candidate_execution,
    )
    .await?;
    let baseline_status = state
        .store
        .write_receipt_by_id(&request.baseline.canonical_receipt.write_id)
        .await?
        .context("authoritative replay baseline receipt no longer resolves")?
        .status;
    Ok(json!({
        "accepted": true,
        "replayed": request.replayed,
        "sealed_set": authority.sealed_set,
        "cases": authority.cases,
        "snapshots": authority.snapshots,
        "baseline_execution": request.baseline.receipt_body,
        "candidate_execution": authority.candidate_execution,
        "canonical_receipts": {
            "records": record_receipts,
            "baseline_execution": (request.baseline.canonical_receipt.clone(), baseline_status),
            "candidate_execution": candidate_receipt
        }
    }))
}

fn maybe_inject_m2_failure(variable: &str, key: &str, checkpoint: &str) -> Result<()> {
    if cfg!(debug_assertions)
        && std::env::var(variable)
            .ok()
            .is_some_and(|configured| configured == key)
    {
        anyhow::bail!("injected M2 failure after {checkpoint}");
    }
    Ok(())
}

fn canonical_trace_reference(
    contract: &CanonicalTraceCompletenessContract,
    kind: CanonicalTraceEvidenceKind,
) -> Result<String> {
    contract
        .evidence
        .iter()
        .find(|evidence| evidence.kind == kind)
        .map(|evidence| evidence.reference.clone())
        .with_context(|| format!("canonical trace is missing {kind:?}"))
}

fn validate_canonical_replay_request(
    input: &ReplayRunToolInput,
) -> Result<(Vec<String>, ReplaySetRole)> {
    let mut trace_refs = input.trace_refs.clone();
    trace_refs.sort();
    trace_refs.dedup();
    if trace_refs.len() < 2 || trace_refs.len() > 20 {
        anyhow::bail!("sealed replay set requires 2 to 20 distinct canonical traces");
    }
    if input.set_name.trim().is_empty() || input.set_version == 0 {
        anyhow::bail!("sealed replay set requires a name and positive version");
    }
    let role = match input.set_role.as_str() {
        "fixed" => ReplaySetRole::Fixed,
        "holdout" => ReplaySetRole::Holdout,
        _ => anyhow::bail!("set_role must be fixed or holdout"),
    };
    if input.baseline_policy.schema_version != "1"
        || input.candidate_policy.schema_version != "1"
        || input.baseline_policy.evaluator_version != input.evaluator_version
        || input.candidate_policy.evaluator_version != input.evaluator_version
        || input.baseline_policy.minimum_pass_basis_points > 10_000
        || input.candidate_policy.minimum_pass_basis_points > 10_000
        || canonical_struct_hash(&input.baseline_policy)?
            == canonical_struct_hash(&input.candidate_policy)?
        || input.baseline_version.trim().is_empty()
        || input.candidate_version.trim().is_empty()
        || input.sealed_context_version.trim().is_empty()
        || input.evaluator_version.trim().is_empty()
    {
        anyhow::bail!("sealed replay versions, baseline, and candidate must be explicit");
    }
    Ok((trace_refs, role))
}

async fn persist_l11_record<T: serde::Serialize>(
    state: &McpState,
    context: AuthenticatedRequestContext,
    project_id: ProjectId,
    task_id: TaskId,
    kind: CanonicalReceiptKind,
    key: &str,
    record: &T,
) -> Result<(WriteReceiptRef, WriteStatus)> {
    write_canonical_observation(state, context, project_id, Some(task_id), kind, key, record).await
}

async fn reconcile_l11_record<T>(
    state: &McpState,
    context: AuthenticatedRequestContext,
    scope: (ProjectId, TaskId),
    kind: CanonicalReceiptKind,
    key: &str,
    body: &T,
) -> Result<(WriteReceiptRef, WriteStatus)>
where
    T: PartialEq + serde::de::DeserializeOwned + serde::Serialize,
{
    let (project_id, task_id) = scope;
    let expected_write = deterministic_canonical_write_id(project_id, Some(task_id), kind, key);
    if let Some(existing) = state
        .store
        .canonical_record_by_write_id::<T>(
            project_id,
            Some(task_id),
            &[kind.as_str()],
            expected_write,
        )
        .await?
    {
        if existing.receipt_kind != kind.as_str() || existing.receipt_body != *body {
            anyhow::bail!("canonical secondary record conflicts with its authoritative primary");
        }
        let status = state
            .store
            .write_receipt_by_id(&expected_write)
            .await?
            .context("canonical secondary write receipt no longer resolves")?
            .status;
        return Ok((existing.canonical_receipt, status));
    }
    persist_l11_record(state, context, project_id, task_id, kind, key, body).await
}

fn dispatch_replay_report(state: &McpState) -> Value {
    json!({
        "component": "replay_report",
        "run": read_j0_latest_value(&state.root, "replay-runs").ok(),
        "verdict": read_j0_latest_value(&state.root, "replay-verdicts").ok()
    })
}

#[allow(clippy::too_many_lines)]
async fn dispatch_sleep_run(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    require_l11_controller_authority(state)?;
    let input: SleepRunToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 sleep task_id")?;
    let task = require_l11_task(state, project_id, task_id, input.expected_task_revision).await?;
    if !input.dry_run {
        anyhow::bail!("L11 sleep MCP is candidate-only and requires dry_run=true");
    }
    if input.trace_refs.is_empty() || input.trace_refs.len() > 20 {
        anyhow::bail!("sleep requires between 1 and 20 requested trace refs");
    }
    let mut contracts = Vec::with_capacity(input.trace_refs.len());
    for trace_ref in &input.trace_refs {
        contracts.push(
            require_registered_trace(state, &task, trace_ref)
                .await?
                .receipt_body,
        );
    }
    if contracts.len() != input.trace_refs.len() {
        anyhow::bail!("sleep input contains an unregistered or duplicate canonical trace");
    }
    let fingerprint = canonical_struct_hash(&input)?;
    let bundle_key = l11_idempotency_key(&input.idempotency_key, "sleep-bundle")?;
    let expected_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::SleepConsolidationBundle,
        &bundle_key,
    );
    let existing = state
        .store
        .canonical_record_by_write_id::<SleepConsolidationBundle>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::SleepConsolidationBundle.as_str()],
            expected_write,
        )
        .await?;
    let (bundle, receipt, write_status, replayed) = if let Some(existing) = existing {
        if !existing
            .receipt_body
            .run
            .reasoning_route_ref
            .contains(&l11_fingerprint_marker(&fingerprint))
        {
            anyhow::bail!("sleep idempotency conflict");
        }
        validate_sleep_bundle(&existing.receipt_body)?;
        (
            existing.receipt_body.clone(),
            existing.canonical_receipt.clone(),
            WriteStatus::IdempotentReplay,
            true,
        )
    } else {
        let mut bundle = SleepConsolidationService::run_with_artifacts(
            SleepRunInput {
                project_id,
                trigger: input.trigger,
                dry_run: input.dry_run,
                input_traces: input.trace_refs.clone(),
            },
            &contracts,
            IncidentService::new(&state.root).lockdown_active()?,
        )?;
        bundle.run.input_scope.task_ids = vec![task_id];
        bundle.run.reasoning_route_ref = format!(
            "deterministic:sleep-consolidation-v3; {}",
            l11_fingerprint_marker(&fingerprint)
        );
        finalize_sleep_bundle_identity(&mut bundle)?;
        validate_sleep_bundle(&bundle)?;
        let (receipt, write_status) = write_canonical_observation(
            state,
            context,
            project_id,
            Some(task_id),
            CanonicalReceiptKind::SleepConsolidationBundle,
            &bundle_key,
            &bundle,
        )
        .await?;
        (bundle, receipt, write_status, false)
    };
    let artifact_receipts = reconcile_sleep_artifacts(
        state,
        context,
        project_id,
        task_id,
        &input.idempotency_key,
        &bundle,
    )
    .await?;
    write_json_report(&j0_latest_path(&state.root, "sleep"), &bundle)?;
    Ok(json!({
        "accepted": true,
        "replayed": replayed,
        "bundle": bundle,
        "run": bundle.run,
        "artifacts": bundle.artifacts,
        "artifact_receipts": artifact_receipts,
        "canonical_receipt": receipt,
        "write_status": write_status
    }))
}

fn finalize_sleep_bundle_identity(bundle: &mut SleepConsolidationBundle) -> Result<()> {
    let bundle_hash = canonical_struct_hash(&json!({
        "run": bundle.run,
        "artifacts": bundle.artifacts,
    }))?;
    bundle.bundle_id = format!("sleep-bundle:{bundle_hash}");
    bundle.bundle_hash = bundle_hash;
    Ok(())
}

fn validate_sleep_bundle(bundle: &SleepConsolidationBundle) -> Result<()> {
    let expected_hash = canonical_struct_hash(&json!({
        "run": bundle.run,
        "artifacts": bundle.artifacts,
    }))?;
    let kinds = bundle
        .artifacts
        .iter()
        .map(|artifact| artifact.artifact_kind)
        .collect::<std::collections::BTreeSet<_>>();
    if bundle.bundle_hash != expected_hash
        || bundle.bundle_id != format!("sleep-bundle:{expected_hash}")
        || bundle.artifacts.len() != 5
        || kinds.len() != 5
        || bundle.artifacts.iter().any(|artifact| {
            artifact.body["sleep_run_ref"] != bundle.run.sleep_run_id
                || validate_sleep_artifact(artifact).is_err()
        })
    {
        anyhow::bail!("sleep aggregate is incomplete, tampered, or non-authoritative");
    }
    Ok(())
}

async fn reconcile_sleep_artifacts(
    state: &McpState,
    context: AuthenticatedRequestContext,
    project_id: ProjectId,
    task_id: TaskId,
    idempotency_key: &str,
    bundle: &SleepConsolidationBundle,
) -> Result<Vec<Value>> {
    let mut receipts = Vec::new();
    for (index, artifact) in bundle.artifacts.iter().enumerate() {
        let key = l11_idempotency_key(
            idempotency_key,
            &format!(
                "sleep-artifact-{}-{index}",
                artifact.artifact_kind.receipt_kind()
            ),
        )?;
        let kind = sleep_artifact_receipt_kind(artifact.artifact_kind);
        let expected_write =
            deterministic_canonical_write_id(project_id, Some(task_id), kind, &key);
        let existing = state
            .store
            .canonical_record_by_write_id::<eliot_types::SleepCandidateArtifact>(
                project_id,
                Some(task_id),
                &[kind.as_str()],
                expected_write,
            )
            .await?;
        let (receipt, write_status) = match existing {
            None => {
                write_canonical_observation(
                    state,
                    context,
                    project_id,
                    Some(task_id),
                    kind,
                    &key,
                    artifact,
                )
                .await?
            }
            Some(record)
                if record.receipt_kind == kind.as_str() && record.receipt_body == *artifact =>
            {
                (record.canonical_receipt, WriteStatus::IdempotentReplay)
            }
            _ => anyhow::bail!(
                "sleep secondary reconciliation found a conflicting canonical artifact"
            ),
        };
        receipts.push(json!({
            "artifact": artifact,
            "canonical_receipt": receipt,
            "write_status": write_status
        }));
        maybe_inject_sleep_reconciliation_failure(index + 1)?;
    }
    for (index, artifact) in bundle.artifacts.iter().enumerate() {
        let key = l11_idempotency_key(
            idempotency_key,
            &format!(
                "sleep-artifact-{}-{index}",
                artifact.artifact_kind.receipt_kind()
            ),
        )?;
        let kind = sleep_artifact_receipt_kind(artifact.artifact_kind);
        let expected_write =
            deterministic_canonical_write_id(project_id, Some(task_id), kind, &key);
        let persisted = state
            .store
            .canonical_record_by_write_id::<eliot_types::SleepCandidateArtifact>(
                project_id,
                Some(task_id),
                &[kind.as_str()],
                expected_write,
            )
            .await?;
        if persisted.is_none_or(|record| record.receipt_body != *artifact) {
            anyhow::bail!("sleep secondary reconciliation is incomplete or conflicting");
        }
    }
    Ok(receipts)
}

fn maybe_inject_sleep_reconciliation_failure(completed: usize) -> Result<()> {
    if cfg!(debug_assertions)
        && std::env::var("ELIOT_TEST_M2_SLEEP_FAIL_AFTER_SECONDARIES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            == Some(completed)
    {
        anyhow::bail!("injected sleep secondary reconciliation failure");
    }
    Ok(())
}

const fn sleep_artifact_receipt_kind(kind: SleepCandidateArtifactKind) -> CanonicalReceiptKind {
    match kind {
        SleepCandidateArtifactKind::Procedure => CanonicalReceiptKind::ProcedureCandidate,
        SleepCandidateArtifactKind::ForgettingAction => CanonicalReceiptKind::ForgettingCandidate,
        SleepCandidateArtifactKind::Test => CanonicalReceiptKind::TestCandidate,
        SleepCandidateArtifactKind::ReplayCase => CanonicalReceiptKind::ReplayCaseCandidate,
        SleepCandidateArtifactKind::Dream => CanonicalReceiptKind::DreamCandidate,
    }
}

fn validate_sleep_artifact(artifact: &eliot_types::SleepCandidateArtifact) -> Result<()> {
    let expected_prefix = match artifact.artifact_kind {
        SleepCandidateArtifactKind::Procedure => "procedure-candidate:",
        SleepCandidateArtifactKind::ForgettingAction => "forgetting-candidate:",
        SleepCandidateArtifactKind::Test => "test-candidate:",
        SleepCandidateArtifactKind::ReplayCase => "replay-case-candidate:",
        SleepCandidateArtifactKind::Dream => "dream-candidate:",
    };
    if !artifact.candidate_only
        || artifact.required_replay.replay_marker.is_some()
        || !artifact.required_replay.required
        || artifact.prohibited_direct_effects.is_empty()
        || artifact.source_trace_ref.trim().is_empty()
        || artifact.source_trace_contract_ref.trim().is_empty()
        || !artifact.artifact_id.starts_with(expected_prefix)
    {
        anyhow::bail!("sleep emitted an unsafe, dangling, or non-candidate artifact");
    }
    Ok(())
}

#[allow(clippy::too_many_lines)]
async fn dispatch_meta_experiment_run(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    require_l11_controller_authority(state)?;
    let input: MetaExperimentToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 meta task_id")?;
    let task = require_l11_task(state, project_id, task_id, input.expected_task_revision).await?;
    let fingerprint = canonical_struct_hash(&input)?;
    let experiment_key = l11_idempotency_key(&input.idempotency_key, "meta-experiment")?;
    let expected_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::HarnessExperiment,
        &experiment_key,
    );
    let existing = state
        .store
        .canonical_record_by_write_id::<eliot_types::HarnessExperimentRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::HarnessExperiment.as_str()],
            expected_write,
        )
        .await?;
    if let Some(existing) = existing {
        if !existing
            .receipt_body
            .notes
            .contains(&l11_fingerprint_marker(&fingerprint))
        {
            anyhow::bail!("meta experiment idempotency conflict");
        }
        revalidate_meta_experiment_trace_authority(state, &task, &existing.receipt_body).await?;
        return reconcile_authoritative_meta_experiment(state, context, &input, &existing, true)
            .await;
    }
    if !meta_change_class_supported(input.change_class) {
        anyhow::bail!(
            "unsupported meta change class: only replay-threshold verification_map is executable"
        );
    }
    let fixed_baseline = canonical_execution_by_id(
        state,
        project_id,
        task_id,
        &input.fixed_baseline_execution_id,
        "fixed baseline",
    )
    .await?;
    let fixed_candidate = canonical_execution_by_id(
        state,
        project_id,
        task_id,
        &input.fixed_candidate_execution_id,
        "fixed candidate",
    )
    .await?;
    let holdout_baseline = canonical_execution_by_id(
        state,
        project_id,
        task_id,
        &input.holdout_baseline_execution_id,
        "holdout baseline",
    )
    .await?;
    let holdout_candidate = canonical_execution_by_id(
        state,
        project_id,
        task_id,
        &input.holdout_candidate_execution_id,
        "holdout candidate",
    )
    .await?;
    for execution in [
        &fixed_baseline,
        &fixed_candidate,
        &holdout_baseline,
        &holdout_candidate,
    ] {
        revalidate_execution_trace_authority(state, &task, &execution.receipt_body).await?;
    }
    let fixed_set = canonical_set_for_execution(
        state,
        project_id,
        task_id,
        &fixed_candidate,
        ReplaySetRole::Fixed,
    )
    .await?;
    let holdout_set = canonical_set_for_execution(
        state,
        project_id,
        task_id,
        &holdout_candidate,
        ReplaySetRole::Holdout,
    )
    .await?;
    let baseline_payload = ExperimentalMetaPolicyPayload::ReplayThresholdV1 {
        policy: input.baseline_policy.clone(),
    };
    let candidate_payload = ExperimentalMetaPolicyPayload::ReplayThresholdV1 {
        policy: input.candidate_policy.clone(),
    };
    let baseline_policy_hash = canonical_struct_hash(&baseline_payload)?;
    let candidate_policy_hash = canonical_struct_hash(&candidate_payload)?;
    let assessment = MetaHarnessService::assess_canonical(CanonicalMetaExperimentInput {
        project_id,
        eval_run_id: EvalRunId::from_str(&input.eval_run_id).context("parse eval_run_id")?,
        verdict_id: None,
        profile_id: "canonical-meta-replay-threshold-v1".to_owned(),
        candidate_ref: candidate_policy_hash.clone(),
        change_class: input.change_class,
        changed_variables: input.changed_variables.clone(),
        coupled_change_rationale: input.coupled_change_rationale.clone(),
        baseline_policy_hash,
        candidate_policy_hash,
        fixed_set: fixed_set.receipt_body,
        holdout_set: holdout_set.receipt_body,
        fixed_baseline: fixed_baseline.receipt_body.clone(),
        fixed_candidate: fixed_candidate.receipt_body.clone(),
        holdout_baseline: holdout_baseline.receipt_body.clone(),
        holdout_candidate: holdout_candidate.receipt_body.clone(),
        threshold: input.candidate_policy.clone(),
        attempted_fence: input.attempted_fence.clone(),
    })?;
    let mut experiment = assessment.records.experiment.clone();
    experiment.notes.push(l11_fingerprint_marker(&fingerprint));
    experiment.authoritative_metric_evidence = assessment.records.metric_evidence.clone();
    experiment.authoritative_isolation_rejection = assessment.records.isolation_rejection.clone();
    experiment.authoritative_policy_candidate = if assessment.eligible_for_promotion {
        Some(MetaPolicyExecutor::stage(
            project_id,
            experiment.harness_experiment_record_id.to_string(),
            baseline_payload,
            candidate_payload,
        )?)
    } else {
        None
    };
    let (receipt, _) = write_canonical_observation(
        state,
        context,
        project_id,
        Some(task_id),
        CanonicalReceiptKind::HarnessExperiment,
        &experiment_key,
        &experiment,
    )
    .await?;
    maybe_inject_m2_failure(
        "ELIOT_TEST_M2_META_FAIL_AFTER_EXPERIMENT_PRIMARY",
        &input.idempotency_key,
        "meta experiment primary",
    )?;
    let persisted = state
        .store
        .canonical_record_by_write_id::<eliot_types::HarnessExperimentRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::HarnessExperiment.as_str()],
            receipt.write_id,
        )
        .await?
        .context("canonical meta experiment was not rehydrated after write")?;
    reconcile_authoritative_meta_experiment(state, context, &input, &persisted, false).await
}

struct AuthoritativeMetaRecords<'a> {
    rejection: Option<&'a eliot_types::MetaIsolationRejectionRecord>,
    candidate: Option<&'a eliot_types::ExperimentalMetaPolicyCandidate>,
}

fn authoritative_meta_records<'a>(
    experiment: &'a eliot_types::HarnessExperimentRecord,
    fingerprint: &str,
) -> Result<AuthoritativeMetaRecords<'a>> {
    let experiment_ref = experiment.harness_experiment_record_id.to_string();
    let records = AuthoritativeMetaRecords {
        rejection: experiment.authoritative_isolation_rejection.as_ref(),
        candidate: experiment.authoritative_policy_candidate.as_ref(),
    };
    if !experiment
        .notes
        .contains(&l11_fingerprint_marker(fingerprint))
        || experiment.authoritative_metric_evidence.is_empty()
        || records.rejection.is_some_and(|record| {
            record.source_experiment_ref != experiment_ref
                || record.decision != MetaExperimentDecision::Rejected
        })
        || records.candidate.is_some_and(|record| {
            record.source_experiment_ref != experiment_ref
                || record.state != ExperimentalMetaPolicyState::Experimental
        })
        || (records.rejection.is_some() && records.candidate.is_some())
        || (experiment.decision == MetaExperimentDecision::Rejected) != records.rejection.is_some()
    {
        anyhow::bail!("meta experiment authoritative primary is incomplete or conflicting");
    }
    Ok(records)
}

async fn reconcile_authoritative_meta_experiment(
    state: &McpState,
    context: AuthenticatedRequestContext,
    input: &MetaExperimentToolInput,
    primary: &CanonicalRecord<eliot_types::HarnessExperimentRecord>,
    replayed: bool,
) -> Result<Value> {
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id)?;
    let fingerprint = canonical_struct_hash(input)?;
    let experiment = &primary.receipt_body;
    let records = authoritative_meta_records(experiment, &fingerprint)?;
    let rejection = records.rejection;
    let candidate = records.candidate;
    let scope = (project_id, task_id);
    let mut metric_receipts = Vec::new();
    for (index, metric) in experiment.authoritative_metric_evidence.iter().enumerate() {
        let key = l11_idempotency_key(&input.idempotency_key, &format!("meta-metric-{index}"))?;
        metric_receipts.push(
            reconcile_l11_record(
                state,
                context,
                scope,
                CanonicalReceiptKind::MetaMetricEvidence,
                &key,
                metric,
            )
            .await?,
        );
    }
    let isolation_receipt = if let Some(rejection) = rejection {
        let key = l11_idempotency_key(&input.idempotency_key, "meta-isolation-rejection")?;
        Some(
            reconcile_l11_record(
                state,
                context,
                scope,
                CanonicalReceiptKind::MetaIsolationRejection,
                &key,
                rejection,
            )
            .await?,
        )
    } else {
        None
    };
    require_receipted_meta_rejection(rejection.is_some(), isolation_receipt.is_some())?;
    let policy_candidate = if let Some(candidate) = candidate {
        let key = l11_idempotency_key(&input.idempotency_key, "meta-policy-candidate")?;
        let candidate_receipt = reconcile_l11_record(
            state,
            context,
            scope,
            CanonicalReceiptKind::ExperimentalPolicyCandidate,
            &key,
            candidate,
        )
        .await?;
        Some(json!({
            "candidate": candidate,
            "promotion_action_hash": MetaPolicyExecutor::exact_action_hash(
                candidate,
                MetaPolicyExecutionAction::Promote,
            )?,
            "canonical_receipt": candidate_receipt
        }))
    } else {
        None
    };
    let primary_status = state
        .store
        .write_receipt_by_id(&primary.canonical_receipt.write_id)
        .await?
        .context("meta experiment primary receipt no longer resolves")?
        .status;
    Ok(json!({
        "accepted": rejection.is_none(),
        "replayed": replayed,
        "assessment": {
            "records": {
                "experiment": experiment,
                "metric_evidence": experiment.authoritative_metric_evidence,
                "isolation_rejection": rejection
            },
            "eligible_for_promotion": candidate.is_some(),
            "gate_results": [],
            "blocking_reasons": experiment.notes
        },
        "experiment": experiment,
        "policy_candidate": policy_candidate,
        "experiment_revision": primary.memory_revision,
        "canonical_receipt": primary.canonical_receipt,
        "write_status": primary_status,
        "metric_receipts": metric_receipts,
        "isolation_rejection": rejection,
        "isolation_rejection_receipt": isolation_receipt
    }))
}

fn require_receipted_meta_rejection(has_rejection: bool, has_receipt: bool) -> Result<()> {
    if has_rejection && !has_receipt {
        anyhow::bail!("meta isolation rejection cannot be returned without a canonical receipt");
    }
    Ok(())
}

const fn meta_change_class_supported(change_class: MetaCandidateChangeClass) -> bool {
    matches!(change_class, MetaCandidateChangeClass::VerificationMap)
}

async fn canonical_execution_by_id(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    execution_id: &str,
    label: &str,
) -> Result<CanonicalRecord<CanonicalReplayExecutionRecord>> {
    let records = state
        .store
        .canonical_records_by_subject_ref::<CanonicalReplayExecutionRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::SealedReplayRun.as_str()],
            execution_id,
            1,
        )
        .await?;
    let record = records
        .into_iter()
        .next()
        .with_context(|| format!("{label} sealed execution is not canonical for this task"))?;
    if record.receipt_body.execution_id != execution_id {
        anyhow::bail!("{label} sealed execution subject identity is inconsistent");
    }
    ReplayRunnerService::validate_canonical_execution_identity(&record.receipt_body)?;
    Ok(record)
}

static M2_META_COMMIT_SERIALIZER: std::sync::OnceLock<tokio::sync::Mutex<()>> =
    std::sync::OnceLock::new();

fn m2_meta_commit_serializer() -> &'static tokio::sync::Mutex<()> {
    M2_META_COMMIT_SERIALIZER.get_or_init(|| tokio::sync::Mutex::new(()))
}

async fn revalidate_execution_trace_authority(
    state: &McpState,
    task: &TaskContract,
    execution: &CanonicalReplayExecutionRecord,
) -> Result<()> {
    ReplayRunnerService::validate_canonical_execution_identity(execution)?;
    let refs = execution
        .audit
        .trace_contract_refs
        .iter()
        .collect::<std::collections::BTreeSet<_>>();
    if refs.len() < 2 {
        anyhow::bail!("canonical replay execution no longer has two sealed trace members");
    }
    for contract_ref in refs {
        let mut contracts = state
            .store
            .canonical_records_by_subject_ref::<CanonicalTraceCompletenessContract>(
                task.project_id,
                Some(task.task_id),
                &[CanonicalReceiptKind::TraceCompletenessContract.as_str()],
                contract_ref,
                2,
            )
            .await?;
        if contracts.len() != 1 || contracts[0].receipt_body.contract_id != *contract_ref {
            anyhow::bail!(
                "canonical replay trace contract is missing or ambiguous: {contract_ref}"
            );
        }
        let contract = contracts
            .pop()
            .context("canonical replay trace contract disappeared")?;
        revalidate_canonical_trace(state, task, &contract.receipt_body).await?;
    }
    Ok(())
}

async fn revalidate_meta_experiment_trace_authority(
    state: &McpState,
    task: &TaskContract,
    experiment: &eliot_types::HarnessExperimentRecord,
) -> Result<()> {
    let execution_refs = experiment
        .replay_run_refs
        .iter()
        .chain(&experiment.holdout_run_refs)
        .collect::<std::collections::BTreeSet<_>>();
    if execution_refs.len() < 2 {
        anyhow::bail!("canonical meta experiment lost fixed or holdout replay authority");
    }
    for execution_ref in execution_refs {
        let execution = canonical_execution_by_id(
            state,
            task.project_id,
            task.task_id,
            execution_ref,
            "canonical meta replay",
        )
        .await?;
        revalidate_execution_trace_authority(state, task, &execution.receipt_body).await?;
    }
    Ok(())
}

async fn canonical_set_for_execution(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    execution: &CanonicalRecord<CanonicalReplayExecutionRecord>,
    role: ReplaySetRole,
) -> Result<CanonicalRecord<SealedReplaySetRecord>> {
    let records = state
        .store
        .canonical_records_by_subject_ref::<SealedReplaySetRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ReplaySet.as_str()],
            &execution.receipt_body.sealed_set_hash,
            128,
        )
        .await?;
    records
        .into_iter()
        .find(|record| record.receipt_body.role == role)
        .with_context(|| format!("sealed {role:?} replay set is not canonical"))
}

fn meta_policy_action_replay_result(
    action: MetaPolicyExecutionAction,
    execution: &CanonicalRecord<eliot_types::MetaPolicyExecutionReceipt>,
    resulting_candidate: &eliot_types::ExperimentalMetaPolicyCandidate,
    candidate_receipt: &(WriteReceiptRef, WriteStatus),
    action_receipt: &(WriteReceiptRef, WriteStatus),
) -> Result<Value> {
    let mut result = json!({
        "accepted": true,
        "replayed": true,
        "action": match action {
            MetaPolicyExecutionAction::Promote => "promote",
            MetaPolicyExecutionAction::Rollback => "rollback",
        },
        "policy_candidate": resulting_candidate,
        "canonical_receipts": {
            "candidate_state": candidate_receipt
        }
    });
    match action {
        MetaPolicyExecutionAction::Promote => {
            result["promotion"] = json!(execution.receipt_body);
            result["rollback_action_hash"] = json!(MetaPolicyExecutor::exact_action_hash(
                resulting_candidate,
                MetaPolicyExecutionAction::Rollback,
            )?);
            result["canonical_receipts"]["promotion"] = json!(action_receipt);
        }
        MetaPolicyExecutionAction::Rollback => {
            result["rollback"] = json!(execution.receipt_body);
            result["canonical_receipts"]["rollback"] = json!(action_receipt);
        }
    }
    Ok(result)
}

async fn rehydrate_meta_policy_action_replay(
    state: &McpState,
    context: AuthenticatedRequestContext,
    project_id: ProjectId,
    task_id: TaskId,
    input: &MetaDispositionToolInput,
) -> Result<Option<Value>> {
    let (action, kind, action_suffix, state_suffix) = if input.rollback_requested {
        (
            MetaPolicyExecutionAction::Rollback,
            CanonicalReceiptKind::MetaPolicyRollback,
            "meta-policy-rollback",
            "meta-policy-rolled-back",
        )
    } else if input.decision == MetaExperimentDecision::Promoted {
        (
            MetaPolicyExecutionAction::Promote,
            CanonicalReceiptKind::MetaPolicyPromotion,
            "meta-policy-promotion",
            "meta-policy-promoted",
        )
    } else {
        return Ok(None);
    };
    let action_key = l11_idempotency_key(&input.idempotency_key, action_suffix)?;
    let expected_action_write =
        deterministic_canonical_write_id(project_id, Some(task_id), kind, &action_key);
    let Some(execution) = state
        .store
        .canonical_record_by_write_id::<eliot_types::MetaPolicyExecutionReceipt>(
            project_id,
            Some(task_id),
            &[kind.as_str()],
            expected_action_write,
        )
        .await?
    else {
        return Ok(None);
    };
    if execution.receipt_body.action != action
        || execution.receipt_body.exact_action_hash != input.expected_action_hash
        || execution.receipt_body.operator_command_ref != input.operator_command_ref
    {
        anyhow::bail!("meta policy idempotency key was reused for a different exact action");
    }
    let state_key = l11_idempotency_key(&input.idempotency_key, state_suffix)?;
    let expected_state_write = deterministic_canonical_write_id(
        project_id,
        Some(task_id),
        CanonicalReceiptKind::ExperimentalPolicyCandidate,
        &state_key,
    );
    let expected_state = match action {
        MetaPolicyExecutionAction::Promote => ExperimentalMetaPolicyState::Promoted,
        MetaPolicyExecutionAction::Rollback => ExperimentalMetaPolicyState::RolledBack,
    };
    let resulting_candidate = execution
        .receipt_body
        .resulting_candidate
        .as_ref()
        .context("meta policy action has no authoritative resulting candidate state")?;
    if resulting_candidate.state != expected_state
        || resulting_candidate.candidate_id != execution.receipt_body.candidate_id
    {
        anyhow::bail!("meta policy action and candidate state are not an exact pair");
    }
    let candidate_receipt = reconcile_l11_record(
        state,
        context,
        (project_id, task_id),
        CanonicalReceiptKind::ExperimentalPolicyCandidate,
        &state_key,
        resulting_candidate,
    )
    .await?;
    if candidate_receipt.0.write_id != expected_state_write {
        anyhow::bail!("meta policy candidate reconciliation used a non-authoritative write id");
    }
    let action_status = state
        .store
        .write_receipt_by_id(&execution.canonical_receipt.write_id)
        .await?
        .context("meta policy action write receipt no longer resolves")?
        .status;
    let action_receipt = (execution.canonical_receipt.clone(), action_status);
    Ok(Some(meta_policy_action_replay_result(
        action,
        &execution,
        resulting_candidate,
        &candidate_receipt,
        &action_receipt,
    )?))
}

async fn canonical_meta_experiment(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    experiment_id: &str,
) -> Result<CanonicalRecord<eliot_types::HarnessExperimentRecord>> {
    let records = state
        .store
        .canonical_records_by_subject_ref::<eliot_types::HarnessExperimentRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::HarnessExperiment.as_str()],
            experiment_id,
            2,
        )
        .await?;
    records
        .into_iter()
        .find(|record| {
            record.receipt_body.harness_experiment_record_id.to_string() == experiment_id
        })
        .context("canonical meta experiment authority is missing")
}

async fn current_meta_policy_candidate(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    experiment: &eliot_types::HarnessExperimentRecord,
) -> Result<Option<CanonicalRecord<eliot_types::ExperimentalMetaPolicyCandidate>>> {
    let Some(authoritative) = experiment.authoritative_policy_candidate.as_ref() else {
        return Ok(None);
    };
    let mut records = state
        .store
        .canonical_records_by_subject_ref::<eliot_types::ExperimentalMetaPolicyCandidate>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::ExperimentalPolicyCandidate.as_str()],
            &authoritative.candidate_id,
            16,
        )
        .await?;
    records.retain(|record| {
        record.receipt_body.candidate_id == authoritative.candidate_id
            && record.receipt_body.source_experiment_ref
                == experiment.harness_experiment_record_id.to_string()
    });
    Ok(records.into_iter().next())
}

async fn canonical_meta_metrics(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    experiment: &eliot_types::HarnessExperimentRecord,
) -> Result<Vec<eliot_types::CanonicalMetaMetricEvidence>> {
    let mut metrics = Vec::with_capacity(experiment.authoritative_metric_evidence.len());
    for authoritative in &experiment.authoritative_metric_evidence {
        let mut records = state
            .store
            .canonical_records_by_subject_ref::<eliot_types::CanonicalMetaMetricEvidence>(
                project_id,
                Some(task_id),
                &[CanonicalReceiptKind::MetaMetricEvidence.as_str()],
                &authoritative.evidence_hash,
                2,
            )
            .await?;
        let record = records
            .drain(..)
            .find(|record| record.receipt_body == *authoritative)
            .context("canonical meta metric evidence is missing")?;
        metrics.push(record.receipt_body);
    }
    Ok(metrics)
}

async fn canonical_meta_rejections(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    experiment_id: &str,
) -> Result<Vec<CanonicalRecord<eliot_types::MetaIsolationRejectionRecord>>> {
    Ok(state
        .store
        .canonical_records_by_subject_ref::<eliot_types::MetaIsolationRejectionRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::MetaIsolationRejection.as_str()],
            experiment_id,
            2,
        )
        .await?
        .into_iter()
        .filter(|record| record.receipt_body.source_experiment_ref == experiment_id)
        .collect())
}

async fn canonical_meta_dispositions(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    experiment_id: &str,
) -> Result<Vec<CanonicalRecord<eliot_types::HarnessExperimentRecord>>> {
    state
        .store
        .canonical_records_by_subject_ref::<eliot_types::HarnessExperimentRecord>(
            project_id,
            Some(task_id),
            &[CanonicalReceiptKind::HarnessDisposition.as_str()],
            experiment_id,
            2,
        )
        .await
        .map_err(Into::into)
}

#[allow(clippy::too_many_lines)]
async fn dispatch_meta_experiment_disposition(
    state: &McpState,
    context: AuthenticatedRequestContext,
    arguments: Value,
) -> Result<Value> {
    require_l11_controller_authority(state)?;
    let _commit_guard = m2_meta_commit_serializer().lock().await;
    let input: MetaDispositionToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 disposition task_id")?;
    let task = require_l11_task(state, project_id, task_id, input.expected_task_revision).await?;
    let experiment =
        canonical_meta_experiment(state, project_id, task_id, &input.experiment_id).await?;
    revalidate_meta_experiment_trace_authority(state, &task, &experiment.receipt_body).await?;
    let actual_revision = experiment
        .memory_revision
        .context("canonical meta experiment has no revision")?;
    if actual_revision.value() != input.expected_experiment_revision {
        anyhow::bail!(
            "stale experiment revision: expected {}, current {}",
            input.expected_experiment_revision,
            actual_revision.value()
        );
    }
    if let Some(replayed) =
        rehydrate_meta_policy_action_replay(state, context, project_id, task_id, &input).await?
    {
        return Ok(replayed);
    }
    let policy_candidate =
        current_meta_policy_candidate(state, project_id, task_id, &experiment.receipt_body).await?;
    if input.rollback_requested {
        let policy_candidate = policy_candidate
            .context("canonical experimental replay-threshold policy candidate not found")?;
        reject_distinct_meta_terminal_action(
            state,
            project_id,
            task_id,
            &policy_candidate.receipt_body.candidate_id,
            MetaPolicyExecutionAction::Rollback,
        )
        .await?;
        if policy_candidate.receipt_body.state != ExperimentalMetaPolicyState::Promoted {
            anyhow::bail!("meta policy rollback requires the current Promoted state exactly");
        }
        let promotions = state
            .store
            .meta_policy_actions_by_candidate(
                project_id,
                task_id,
                &policy_candidate.receipt_body.candidate_id,
                MetaPolicyExecutionAction::Promote,
            )
            .await?;
        if promotions.len() != 1 {
            anyhow::bail!("canonical policy promotion receipt is missing or ambiguous");
        }
        let promotion = &promotions[0];
        let expected_hash = MetaPolicyExecutor::exact_action_hash(
            &policy_candidate.receipt_body,
            MetaPolicyExecutionAction::Rollback,
        )?;
        let authorization = exact_meta_authorization(&input, &expected_hash)?;
        let (rolled_back, rollback) = MetaPolicyExecutor::rollback(
            &policy_candidate.receipt_body,
            &promotion.receipt_body,
            &authorization,
        )?;
        let rollback_key = l11_idempotency_key(&input.idempotency_key, "meta-policy-rollback")?;
        let rollback_receipt = persist_l11_record(
            state,
            context,
            project_id,
            task_id,
            CanonicalReceiptKind::MetaPolicyRollback,
            &rollback_key,
            &rollback,
        )
        .await?;
        maybe_inject_m2_failure(
            "ELIOT_TEST_M2_META_FAIL_AFTER_ACTION",
            &input.idempotency_key,
            "meta rollback action",
        )?;
        let state_key = l11_idempotency_key(&input.idempotency_key, "meta-policy-rolled-back")?;
        let state_receipt = persist_l11_record(
            state,
            context,
            project_id,
            task_id,
            CanonicalReceiptKind::ExperimentalPolicyCandidate,
            &state_key,
            &rolled_back,
        )
        .await?;
        return Ok(json!({
            "accepted": true,
            "action": "rollback",
            "policy_candidate": rolled_back,
            "rollback": rollback,
            "canonical_receipts": {
                "rollback": rollback_receipt,
                "candidate_state": state_receipt
            }
        }));
    }
    if input.decision == MetaExperimentDecision::Promoted {
        let policy_candidate = policy_candidate
            .context("canonical experimental replay-threshold policy candidate not found")?;
        reject_distinct_meta_terminal_action(
            state,
            project_id,
            task_id,
            &policy_candidate.receipt_body.candidate_id,
            MetaPolicyExecutionAction::Promote,
        )
        .await?;
        if policy_candidate.receipt_body.state != ExperimentalMetaPolicyState::Experimental {
            anyhow::bail!("meta policy promotion requires the current Experimental state exactly");
        }
        let experiment_id = experiment
            .receipt_body
            .harness_experiment_record_id
            .to_string();
        let rejections =
            canonical_meta_rejections(state, project_id, task_id, &experiment_id).await?;
        if experiment.receipt_body.decision != MetaExperimentDecision::KeptExperimental
            || !rejections.is_empty()
        {
            anyhow::bail!("rejected or isolated meta experiment cannot promote policy");
        }
        let assessment = CanonicalMetaExperimentAssessment {
            records: eliot_types::CanonicalMetaExperimentRecordSet {
                experiment: experiment.receipt_body.clone(),
                metric_evidence: canonical_meta_metrics(
                    state,
                    project_id,
                    task_id,
                    &experiment.receipt_body,
                )
                .await?,
                isolation_rejection: None,
            },
            eligible_for_promotion: true,
            gate_results: Vec::new(),
            blocking_reasons: Vec::new(),
        };
        let expected_hash = MetaPolicyExecutor::exact_action_hash(
            &policy_candidate.receipt_body,
            MetaPolicyExecutionAction::Promote,
        )?;
        let authorization = exact_meta_authorization(&input, &expected_hash)?;
        let (promoted, promotion) = MetaPolicyExecutor::promote(
            &policy_candidate.receipt_body,
            &assessment,
            &authorization,
        )?;
        let promotion_key = l11_idempotency_key(&input.idempotency_key, "meta-policy-promotion")?;
        let promotion_receipt = persist_l11_record(
            state,
            context,
            project_id,
            task_id,
            CanonicalReceiptKind::MetaPolicyPromotion,
            &promotion_key,
            &promotion,
        )
        .await?;
        maybe_inject_m2_failure(
            "ELIOT_TEST_M2_META_FAIL_AFTER_ACTION",
            &input.idempotency_key,
            "meta promotion action",
        )?;
        let state_key = l11_idempotency_key(&input.idempotency_key, "meta-policy-promoted")?;
        let state_receipt = persist_l11_record(
            state,
            context,
            project_id,
            task_id,
            CanonicalReceiptKind::ExperimentalPolicyCandidate,
            &state_key,
            &promoted,
        )
        .await?;
        let rollback_action_hash =
            MetaPolicyExecutor::exact_action_hash(&promoted, MetaPolicyExecutionAction::Rollback)?;
        return Ok(json!({
            "accepted": true,
            "action": "promote",
            "policy_candidate": promoted,
            "promotion": promotion,
            "rollback_action_hash": rollback_action_hash,
            "canonical_receipts": {
                "promotion": promotion_receipt,
                "candidate_state": state_receipt
            }
        }));
    }
    if !matches!(
        input.decision,
        MetaExperimentDecision::Rejected | MetaExperimentDecision::KeptExperimental
    ) {
        anyhow::bail!("terminal MCP disposition must be REJECTED or KEPT_EXPERIMENTAL");
    }
    let experiment_id = experiment
        .receipt_body
        .harness_experiment_record_id
        .to_string();
    let dispositions =
        canonical_meta_dispositions(state, project_id, task_id, &experiment_id).await?;
    if dispositions.len() > 1 {
        anyhow::bail!("meta experiment has multiple terminal disposition records");
    }
    if let Some(existing) = dispositions.into_iter().next() {
        if existing.receipt_body.decision != input.decision {
            anyhow::bail!("experiment already has a conflicting terminal disposition");
        }
        return Ok(json!({
            "accepted": true,
            "replayed": true,
            "disposition": existing.receipt_body,
            "canonical_receipt": existing.canonical_receipt,
            "disposition_revision": existing.memory_revision
        }));
    }
    let fingerprint = canonical_struct_hash(&input)?;
    let disposition_key = l11_idempotency_key(&input.idempotency_key, "meta-disposition")?;
    let assessment = MetaExperimentAssessment {
        record: experiment.receipt_body.clone(),
        eligible_for_promotion: false,
        gate_results: Vec::new(),
        blocking_reasons: experiment.receipt_body.notes.clone(),
    };
    let mut disposition = MetaDispositionService::apply(
        &assessment,
        MetaDispositionRequest {
            decision: input.decision,
            authorized_command_ref: format!(
                "governor-command:meta-disposition:{}",
                &fingerprint[..16]
            ),
            rollback_target_ref: String::new(),
            rollback_command_ref: String::new(),
        },
    )?;
    disposition.notes.push(l11_fingerprint_marker(&fingerprint));
    let (receipt, write_status) = write_canonical_observation(
        state,
        context,
        project_id,
        Some(task_id),
        CanonicalReceiptKind::HarnessDisposition,
        &disposition_key,
        &disposition,
    )
    .await?;
    Ok(json!({
        "accepted": true,
        "replayed": false,
        "disposition": disposition,
        "canonical_receipt": receipt,
        "write_status": write_status,
        "rollback_receipt": Value::Null
    }))
}

async fn reject_distinct_meta_terminal_action(
    state: &McpState,
    project_id: ProjectId,
    task_id: TaskId,
    candidate_id: &str,
    action: MetaPolicyExecutionAction,
) -> Result<()> {
    if !state
        .store
        .meta_policy_actions_by_candidate(project_id, task_id, candidate_id, action)
        .await?
        .is_empty()
    {
        anyhow::bail!(
            "meta policy terminal action already exists; retry its original idempotency key"
        );
    }
    Ok(())
}

async fn dispatch_l11_status(state: &McpState, arguments: Value) -> Result<Value> {
    let input: L11StatusToolInput = serde_json::from_value(arguments)?;
    let project_id = parse_project_id(&input.project_id)?;
    let task_id = TaskId::from_str(&input.task_id).context("parse L11 status task_id")?;
    let task = require_task(state, project_id, task_id).await?;
    let traces = l11_trace_records(state, project_id, task_id).await?;
    let sleep = state
        .store
        .sleep_view(project_id, Some(task_id), 128)
        .await?;
    let replay = state
        .store
        .replay_view(project_id, Some(task_id), 128)
        .await?;
    let profile = ReplayRunnerService::deterministic_no_mutation_profile();
    let profile_hash = canonical_struct_hash(&profile)?;
    let mut trace_status = Vec::with_capacity(traces.len());
    for canonical in traces {
        let authority = revalidate_canonical_trace(state, &task, &canonical.receipt_body).await;
        trace_status.push(json!({
            "trace": canonical.receipt_body,
            "canonical_receipt": canonical.canonical_receipt,
            "memory_revision": canonical.memory_revision,
            "authority_valid": authority.is_ok(),
            "authority_error": authority.err().map(|error| error.to_string())
        }));
    }
    let sleep_runs = sleep
        .bundles
        .iter()
        .map(|record| {
            json!({
                "run": record.receipt_body.run,
                "bundle_id": record.receipt_body.bundle_id,
                "canonical_receipt": record.canonical_receipt,
                "memory_revision": record.memory_revision
            })
        })
        .collect::<Vec<_>>();
    let candidate_artifacts = sleep
        .bundles
        .iter()
        .flat_map(|record| {
            record.receipt_body.artifacts.iter().map(|artifact| {
                json!({
                    "artifact": artifact,
                    "receipt_kind": artifact.artifact_kind.receipt_kind(),
                    "aggregate_receipt": record.canonical_receipt,
                    "memory_revision": record.memory_revision
                })
            })
        })
        .collect::<Vec<_>>();
    let complete_replay_executions = complete_authoritative_replay_executions(&replay);
    Ok(json!({
        "component": "l11_status",
        "project_id": project_id,
        "task_id": task_id,
        "task_revision": task.memory_revision,
        "replay_profile": {
            "version": profile.profile_id,
            "hash": profile_hash,
            "profile": profile
        },
        "registered_traces": trace_status,
        "sleep_runs": sleep_runs,
        "candidate_artifacts": candidate_artifacts,
        "sealed_replay_sets": replay.sealed_sets,
        "sealed_replay_cases": replay.sealed_cases,
        "sealed_replay_snapshots": replay.sealed_snapshots,
        "sealed_replay_executions": complete_replay_executions,
        "experiments_and_dispositions": replay.harness_experiments,
        "meta_metric_evidence": replay.meta_metrics,
        "meta_isolation_rejections": replay.isolation_rejections,
        "experimental_policy_candidates": replay.policy_candidates,
        "policy_execution_receipts": replay.policy_executions,
        "promotion_boundary": "only replay_threshold_v1 with exact action hash and exact rollback is executable"
    }))
}

fn complete_authoritative_replay_executions(
    replay: &eliot_store::CanonicalReplayView,
) -> Vec<CanonicalRecord<CanonicalReplayExecutionRecord>> {
    let mut complete = Vec::new();
    let mut included = std::collections::BTreeSet::new();
    for baseline in &replay.sealed_executions {
        let Some(authority) = baseline.receipt_body.authoritative_replay.as_deref() else {
            continue;
        };
        let candidate = replay.sealed_executions.iter().find(|record| {
            record.canonical_receipt.write_id == authority.expected_candidate_write_id
                && record.receipt_body == authority.candidate_execution
        });
        let set_complete = replay.sealed_sets.iter().any(|record| {
            record.canonical_receipt.write_id == authority.expected_set_write_id
                && record.receipt_body == authority.sealed_set
        });
        let cases_complete = authority
            .expected_case_write_ids
            .iter()
            .zip(&authority.cases)
            .all(|(write_id, body)| {
                replay.sealed_cases.iter().any(|record| {
                    record.canonical_receipt.write_id == *write_id && record.receipt_body == *body
                })
            });
        let snapshots_complete = authority
            .expected_snapshot_write_ids
            .iter()
            .zip(&authority.snapshots)
            .all(|(write_id, body)| {
                replay.sealed_snapshots.iter().any(|record| {
                    record.canonical_receipt.write_id == *write_id && record.receipt_body == *body
                })
            });
        if set_complete
            && cases_complete
            && snapshots_complete
            && authority.expected_case_write_ids.len() == authority.cases.len()
            && authority.expected_snapshot_write_ids.len() == authority.snapshots.len()
            && let Some(candidate) = candidate
        {
            for record in [baseline, candidate] {
                if included.insert(record.canonical_receipt.write_id) {
                    complete.push(record.clone());
                }
            }
        }
    }
    complete
}

